const STORAGE_KEY = 'blackriver.workspace.artifacts.v05';
const VIEWER_TYPES = new Set(['html', 'code', 'text', 'markdown']);
const DOWNLOAD_TYPES = new Set(['file', 'bundle', 'document']);
const ALL_TYPES = new Set([...VIEWER_TYPES, ...DOWNLOAD_TYPES]);

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function cleanPath(value = 'file.txt') {
  const path = String(value || 'file.txt').replace(/\\/g, '/').replace(/^\/+/, '').split('/').filter((part) => part && part !== '.' && part !== '..').join('/');
  return path || 'file.txt';
}


function looksLikeHtml(content = '', language = '') {
  const text = String(content || '').trim();
  const lang = String(language || '').toLowerCase();
  return lang === 'html' || /<!doctype\s+html|<html(?:\s|>)|<body(?:\s|>)|<canvas(?:\s|>)|<script(?:\s|>)/i.test(text);
}

function normalizeViewerType(type = 'text', language = '', content = '') {
  if (looksLikeHtml(content, language)) return 'html';
  return ALL_TYPES.has(type) ? type : 'text';
}

function normalizeFiles(files = []) {
  if (!Array.isArray(files)) return [];
  return files.slice(0, 128).map((file, index) => ({
    path: cleanPath(file?.path || file?.name || `file-${index + 1}.txt`),
    content: String(file?.content ?? ''),
    mime: String(file?.mime || 'text/plain').slice(0, 120),
  }));
}

export class ArtifactStore extends EventTarget {
  constructor() {
    super();
    this.items = this.load();
    this.activeId = null;
    this.lastTouchedId = null;
    this.diagnostics = new Map();
    this.previewReady = new Set();
  }

  load() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      return Array.isArray(parsed) ? parsed.map((item) => ({
        ...item,
        type: normalizeViewerType(item?.type, item?.language, item?.content),
        files: normalizeFiles(item?.files || []),
      })) : [];
    } catch {
      return [];
    }
  }

  save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.items));
      this.persistenceWarning = '';
    } catch (error) {
      // Large generated bundles can exceed a browser's small localStorage quota.
      // Keep the artifact usable/downloadable for the current session rather than
      // failing the tool call; a future IndexedDB artifact vault can persist very
      // large/binary bundles without changing the public artifact API.
      this.persistenceWarning = error?.message || 'Artifact could not be persisted in browser storage.';
      console.warn('[BlackRiver Artifacts] persistence warning', error);
    }
    this.dispatchEvent(new Event('change'));
  }

  list(conversationId = null, projectId = undefined) {
    let items = conversationId ? this.items.filter((item) => item.conversationId === conversationId) : [...this.items];
    if (projectId !== undefined) items = items.filter((item) => (item.projectId || null) === (projectId || null));
    return items.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  get(id) {
    return this.items.find((item) => item.id === id) || null;
  }

  open(id) {
    const item = this.get(id);
    if (!item || !VIEWER_TYPES.has(item.type)) return null;
    this.activeId = id;
    this.lastTouchedId = id;
    this.dispatchEvent(new CustomEvent('open', { detail: item }));
    return item;
  }

  close() {
    this.activeId = null;
    this.dispatchEvent(new Event('close'));
  }

  create({ title = 'Untitled artifact', type = 'html', language = '', content = '', conversationId = null, projectId = null, filename = '', mime = '', files = [], documentFormat = '' } = {}) {
    const now = Date.now();
    const normalizedType = normalizeViewerType(type, language, content);
    const normalizedFiles = normalizedType === 'bundle' ? normalizeFiles(files) : [];
    const item = {
      id: uid(),
      conversationId,
      projectId: projectId || null,
      title: String(title || 'Untitled artifact').slice(0, 180),
      type: normalizedType,
      language: String(language || ''),
      content: String(content ?? ''),
      filename: cleanPath(filename || (normalizedType === 'bundle' ? `${title || 'artifact'}.zip` : '')),
      mime: String(mime || '').slice(0, 120),
      files: normalizedFiles,
      documentFormat: normalizedType === 'document' ? String(documentFormat || '').toLowerCase().slice(0, 12) : '',
      createdAt: now,
      updatedAt: now,
    };
    this.items.unshift(item);
    if (VIEWER_TYPES.has(item.type)) this.activeId = item.id;
    this.lastTouchedId = item.id;
    this.save();
    this.dispatchEvent(new CustomEvent('created', { detail: item }));
    return item;
  }

  update(id, patch = {}) {
    const item = this.get(id);
    if (!item) throw new Error(`Artifact not found: ${id}`);
    if (patch.title !== undefined) item.title = String(patch.title || item.title).slice(0, 180);
    if (patch.content !== undefined) item.content = String(patch.content ?? '');
    if (patch.language !== undefined) item.language = String(patch.language || '');
    if (patch.filename !== undefined) item.filename = cleanPath(patch.filename || item.filename || 'artifact.txt');
    if (patch.mime !== undefined) item.mime = String(patch.mime || '').slice(0, 120);
    if (patch.files !== undefined) item.files = normalizeFiles(patch.files);
    if (patch.documentFormat !== undefined) item.documentFormat = String(patch.documentFormat || item.documentFormat || '').toLowerCase().slice(0, 12);
    if (patch.type !== undefined && ALL_TYPES.has(patch.type)) item.type = patch.type;
    item.type = normalizeViewerType(item.type, item.language, item.content);
    item.updatedAt = Date.now();
    // Runtime/preview evidence belongs to the previous source revision. Invalidate
    // it at the source-of-truth boundary so background updates cannot inherit a
    // stale green verification state before the new revision actually executes.
    this.clearDiagnostics(item.id);
    if (VIEWER_TYPES.has(item.type)) this.activeId = item.id;
    this.lastTouchedId = item.id;
    this.save();
    this.dispatchEvent(new CustomEvent('updated', { detail: item }));
    return item;
  }

  remove(id) {
    this.items = this.items.filter((item) => item.id !== id);
    if (this.activeId === id) this.activeId = null;
    if (this.lastTouchedId === id) this.lastTouchedId = null;
    this.save();
  }

  detachProject(projectId) {
    if (!projectId) return 0;
    let count = 0;
    for (const item of this.items) {
      if (item.projectId === projectId) { item.projectId = null; count += 1; }
    }
    if (count) this.save();
    return count;
  }

  removeByConversation(conversationId) {
    if (!conversationId) return 0;
    const before = this.items.length;
    const removedActive = this.activeId && this.get(this.activeId)?.conversationId === conversationId;
    this.items = this.items.filter((item) => item.conversationId !== conversationId);
    if (removedActive) this.activeId = null;
    if (this.lastTouchedId && !this.get(this.lastTouchedId)) this.lastTouchedId = null;
    const removed = before - this.items.length;
    if (removed) this.save();
    return removed;
  }

  setDiagnostic(id, diagnostic = {}) {
    if (!id) return;
    const list = this.diagnostics.get(id) || [];
    const entry = {
      level: String(diagnostic.level || 'error'),
      message: String(diagnostic.message || '').slice(0, 1000),
      at: Number(diagnostic.at) || Date.now(),
    };
    const next = [entry, ...list.filter((item) => item.message !== entry.message)].slice(0, 12);
    this.diagnostics.set(id, next);
    this.dispatchEvent(new CustomEvent('diagnostic', { detail: { id, diagnostics: next } }));
  }

  clearDiagnostics(id) {
    if (!id) return;
    this.diagnostics.delete(id);
    this.previewReady.delete(id);
    this.dispatchEvent(new CustomEvent('diagnostic', { detail: { id, diagnostics: [] } }));
  }

  markPreviewReady(id) {
    if (!id) return;
    this.previewReady.add(id);
    this.dispatchEvent(new CustomEvent('preview-ready', { detail: { id } }));
  }

  inspect(id) {
    const item = this.get(id);
    if (!item) throw new Error(`Artifact not found: ${id}`);
    const diagnostics = [...(this.diagnostics.get(id) || [])];
    const previewReady = this.previewReady.has(id);
    const healthy = !diagnostics.some((entry) => entry.level === 'error');
    return {
      artifact_id: item.id,
      title: item.title,
      type: item.type,
      diagnostics,
      healthy,
      preview_ready: previewReady,
      verified: item.type !== 'html' ? true : (previewReady && healthy),
      updated_at: item.updatedAt,
    };
  }


  async waitForInspection(id, { timeoutMs = 2600, settleMs = 900 } = {}) {
    const item = this.get(id);
    if (!item) throw new Error(`Artifact not found: ${id}`);
    if (item.type !== 'html') return this.inspect(id);
    if (!this.previewReady.has(id)) {
      // The visible Artifact Viewer may belong to another conversation while a
      // background Work turn is running. Ask the host UI for an off-screen
      // sandbox verification render so every HTML mutation is actually executed.
      this.dispatchEvent(new CustomEvent('verification-request', { detail: { id } }));
      await new Promise((resolve) => {
        let finished = false;
        const finish = () => {
          if (finished) return;
          finished = true;
          clearTimeout(timer);
          this.removeEventListener('preview-ready', onReady);
          resolve();
        };
        const onReady = (event) => { if (event?.detail?.id === id) finish(); };
        const timer = setTimeout(finish, Math.max(250, Number(timeoutMs) || 2600));
        this.addEventListener('preview-ready', onReady);
      });
    }
    if (settleMs > 0) await new Promise((resolve) => setTimeout(resolve, Math.max(0, Number(settleMs) || 0)));
    return this.inspect(id);
  }

  get viewerDefinitions() {
    return this.definitions.filter((tool) => ['create_artifact', 'update_artifact', 'read_artifact', 'list_artifacts', 'inspect_artifact'].includes(tool.function?.name));
  }

  get downloadDefinitions() {
    return this.definitions.filter((tool) => ['create_downloadable_file', 'create_zip_artifact', 'create_document', 'update_document', 'read_document', 'create_document_bundle'].includes(tool.function?.name));
  }

  get definitions() {
    return [
      {
        type: 'function',
        function: {
          name: 'create_artifact',
          description: 'Create a complete artifact shown in the BlackRiver Work artifact viewer. Use this for self-contained HTML apps/games, code, documents, or markdown when the user asks you to build or create something and no project file needs to be edited.',
          parameters: {
            type: 'object',
            properties: {
              title: { type: 'string', description: 'Short human-readable artifact title.' },
              type: { type: 'string', enum: ['html', 'code', 'text', 'markdown'], description: 'Artifact kind. Use html for interactive webpages/apps/games.' },
              language: { type: 'string', description: 'Language label such as html, javascript, python, markdown. Optional.' },
              content: { type: 'string', description: 'Complete artifact content. For HTML, provide one self-contained HTML document with inline CSS and JavaScript.' },
            },
            required: ['title', 'type', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'create_downloadable_file',
          description: 'Create one downloadable text/code/data file for the user. Use this in Chat when the user explicitly asks for a file, export, script, document, config, or downloadable deliverable rather than only inline text.',
          parameters: {
            type: 'object',
            properties: {
              title: { type: 'string', description: 'Human-readable file card title.' },
              filename: { type: 'string', description: 'Download filename including extension, for example app.py or config.json.' },
              mime: { type: 'string', description: 'MIME type such as text/plain, application/json, text/markdown. Optional.' },
              content: { type: 'string', description: 'Complete file content.' },
            },
            required: ['title', 'filename', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'create_zip_artifact',
          description: 'Create a downloadable ZIP bundle containing multiple text/code files. Use this when the user asks for a multi-file project, package, archive, starter repo, or ZIP. Paths may include folders such as src/main.js.',
          parameters: {
            type: 'object',
            properties: {
              title: { type: 'string', description: 'Human-readable bundle title.' },
              filename: { type: 'string', description: 'ZIP filename, for example my-project.zip.' },
              files: {
                type: 'array',
                minItems: 1,
                maxItems: 128,
                items: {
                  type: 'object',
                  properties: {
                    path: { type: 'string', description: 'Relative path inside the ZIP, for example index.html or src/app.js.' },
                    content: { type: 'string', description: 'Complete file content.' },
                    mime: { type: 'string', description: 'Optional MIME type.' },
                  },
                  required: ['path', 'content'],
                },
              },
            },
            required: ['title', 'files'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'create_document',
          description: 'Create a downloadable real PDF or Microsoft Office document. Use PDF/DOCX for reports and text-heavy documents, XLSX for tables/data, and PPTX for slide decks. Content is Markdown-like for PDF/DOCX/PPTX and CSV/TSV/Markdown-table text for XLSX.',
          parameters: {
            type: 'object',
            properties: {
              format: { type: 'string', enum: ['pdf', 'docx', 'xlsx', 'pptx'], description: 'Output document format.' },
              title: { type: 'string', description: 'Human-readable document title.' },
              filename: { type: 'string', description: 'Filename including the matching extension.' },
              content: { type: 'string', description: 'Complete editable source content. PDF/DOCX/PPTX use Markdown-like text; PPTX separates slides with a line containing ---; XLSX uses CSV, TSV, or a Markdown table.' },
            },
            required: ['format', 'title', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'update_document',
          description: 'Modify a BlackRiver document created earlier in this conversation by replacing its editable source content and regenerating the downloadable file on demand.',
          parameters: {
            type: 'object',
            properties: {
              artifact_id: { type: 'string', description: 'Document artifact id.' },
              title: { type: 'string', description: 'Optional new title.' },
              content: { type: 'string', description: 'Complete replacement source content.' },
            },
            required: ['artifact_id', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'read_document',
          description: 'Read the editable source of a previously generated PDF/DOCX/XLSX/PPTX document before modifying it.',
          parameters: { type: 'object', properties: { artifact_id: { type: 'string' } }, required: ['artifact_id'] },
        },
      },
      {
        type: 'function',
        function: {
          name: 'create_document_bundle',
          description: 'Create a ZIP containing previously generated BlackRiver document artifacts. Use after create_document when the user asks for several office/PDF files bundled together.',
          parameters: {
            type: 'object',
            properties: {
              title: { type: 'string' },
              filename: { type: 'string', description: 'ZIP filename.' },
              artifact_ids: { type: 'array', items: { type: 'string' }, description: 'Document artifact ids to include.' },
            },
            required: ['title', 'artifact_ids'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'update_artifact',
          description: 'Replace or revise an existing BlackRiver viewer artifact. Prefer targeted updates only when you have read the current artifact first.',
          parameters: {
            type: 'object',
            properties: {
              artifact_id: { type: 'string', description: 'Artifact id returned by create_artifact or list_artifacts.' },
              title: { type: 'string', description: 'Optional new title.' },
              content: { type: 'string', description: 'Complete replacement content.' },
            },
            required: ['artifact_id', 'content'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'read_artifact',
          description: 'Read an existing viewer artifact before editing it.',
          parameters: {
            type: 'object',
            properties: { artifact_id: { type: 'string', description: 'Artifact id.' } },
            required: ['artifact_id'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'inspect_artifact',
          description: 'Inspect the current runtime diagnostics for an artifact preview. Use after the user reports a preview bug or after revising an artifact that previously threw a runtime error.',
          parameters: {
            type: 'object',
            properties: { artifact_id: { type: 'string', description: 'Artifact id.' } },
            required: ['artifact_id'],
          },
        },
      },
      {
        type: 'function',
        function: {
          name: 'list_artifacts',
          description: 'List artifacts created in the current conversation.',
          parameters: { type: 'object', properties: {} },
        },
      },
    ];
  }

  async execute(name, args = {}, { conversationId = null, projectId = null } = {}) {
    switch (name) {
      case 'create_document': {
        const format = String(args.format || '').toLowerCase();
        if (!['pdf', 'docx', 'xlsx', 'pptx'].includes(format)) throw new Error('Document format must be pdf, docx, xlsx, or pptx.');
        const ext = `.${format}`;
        const base = String(args.filename || args.title || `blackriver-document${ext}`).trim();
        const filename = base.toLowerCase().endsWith(ext) ? base : `${base.replace(/\.[a-z0-9]+$/i, '')}${ext}`;
        const item = this.create({ title: args.title || filename, type: 'document', language: 'markdown', content: String(args.content || ''), filename, mime: '', documentFormat: format, conversationId, projectId });
        return { artifact_id: item.id, title: item.title, type: item.type, format, filename: item.filename, bytes_source: item.content.length, downloadable: true };
      }
      case 'update_document': {
        const item = this.get(args.artifact_id);
        if (!item || item.type !== 'document') throw new Error('Document artifact not found.');
        this.update(item.id, { title: args.title, content: String(args.content || '') });
        return { artifact_id: item.id, title: item.title, type: item.type, format: item.documentFormat, filename: item.filename, downloadable: true };
      }
      case 'read_document': {
        const item = this.get(args.artifact_id);
        if (!item || item.type !== 'document') throw new Error('Document artifact not found.');
        return { artifact_id: item.id, title: item.title, format: item.documentFormat, filename: item.filename, content: item.content };
      }
      case 'create_document_bundle': {
        const ids = Array.isArray(args.artifact_ids) ? args.artifact_ids.map(String) : [];
        const docs = ids.map((id) => this.get(id)).filter((item) => item?.type === 'document');
        if (!docs.length) throw new Error('No valid document artifacts were supplied.');
        const manifest = docs.map((item) => ({ artifact_id: item.id, filename: item.filename, format: item.documentFormat, title: item.title }));
        const item = this.create({ title: args.title || 'Document bundle', type: 'bundle', filename: args.filename || 'blackriver-documents.zip', files: manifest.map((entry) => ({ path: entry.filename, content: `__BLACKRIVER_DOCUMENT_REF__:${entry.artifact_id}`, mime: 'application/x-blackriver-document-ref' })), conversationId, projectId });
        return { artifact_id: item.id, title: item.title, type: item.type, filename: item.filename, document_refs: manifest };
      }
      case 'create_artifact': {
        const item = this.create({ ...args, conversationId, projectId });
        return {
          status: 'ok', artifact_id: item.id, title: item.title, type: item.type, language: item.language,
          bytes: new Blob([item.content]).size, viewer: 'opened',
        };
      }
      case 'create_downloadable_file': {
        const item = this.create({
          title: args.title || args.filename || 'Download', type: 'file', filename: args.filename || 'artifact.txt',
          mime: args.mime || 'text/plain', content: args.content || '', conversationId, projectId,
        });
        return {
          status: 'ok', artifact_id: item.id, title: item.title, type: item.type, filename: item.filename,
          mime: item.mime, bytes: new Blob([item.content]).size, viewer: 'download',
        };
      }
      case 'create_zip_artifact': {
        const files = normalizeFiles(args.files || []);
        if (!files.length) throw new Error('A ZIP artifact needs at least one file.');
        const item = this.create({
          title: args.title || 'Project bundle', type: 'bundle', filename: args.filename || `${args.title || 'project'}.zip`, files, conversationId, projectId,
        });
        return {
          status: 'ok', artifact_id: item.id, title: item.title, type: item.type, filename: item.filename,
          files: files.length, bytes: files.reduce((sum, file) => sum + new Blob([file.content]).size, 0), viewer: 'download',
        };
      }
      case 'update_artifact': {
        const item = this.update(args.artifact_id, { title: args.title, content: args.content });
        return {
          status: 'ok', artifact_id: item.id, title: item.title, type: item.type,
          bytes: new Blob([item.content]).size, viewer: VIEWER_TYPES.has(item.type) ? 'opened' : 'download',
        };
      }
      case 'read_artifact': {
        const item = this.get(args.artifact_id);
        if (!item) throw new Error(`Artifact not found: ${args.artifact_id}`);
        return {
          artifact_id: item.id, title: item.title, type: item.type, language: item.language,
          content: item.content, filename: item.filename || '', files: item.files || [],
        };
      }
      case 'inspect_artifact': {
        // Give the sandboxed iframe enough time to execute its bootstrap and
        // report synchronous/runtime failures. This makes create → inspect →
        // repair a real agent loop instead of a race against requestAnimationFrame.
        for (let i = 0; i < 16 && !this.previewReady.has(args.artifact_id); i++) {
          await new Promise((resolve) => setTimeout(resolve, 125));
        }
        return this.inspect(args.artifact_id);
      }
      case 'list_artifacts': {
        return {
          artifacts: this.list(conversationId).map((item) => ({
            artifact_id: item.id, title: item.title, type: item.type, language: item.language,
            filename: item.filename || '', files: item.files?.length || 0, updated_at: item.updatedAt,
          })),
        };
      }
      default:
        throw new Error(`Unknown artifact tool: ${name}`);
    }
  }
}
