function id(prefix = 'task') { return `${prefix}_${Math.random().toString(36).slice(2, 9)}`; }

export function createTaskGraph(goal = '', { hasProject = true } = {}) {
  const inspect = { id: id('inspect'), label: hasProject ? 'Inspect context' : 'Understand request', status: 'pending', dependsOn: [], evidence: [] };
  const execute = { id: id('execute'), label: 'Implement', status: 'pending', dependsOn: [inspect.id], evidence: [] };
  const verify = { id: id('verify'), label: 'Verify result', status: 'pending', dependsOn: [execute.id], evidence: [] };
  return { goal: String(goal || '').slice(0, 1800), nodes: [inspect, execute, verify], createdAt: Date.now(), updatedAt: Date.now() };
}

export function advanceTaskGraph(graph, event = {}) {
  if (!graph?.nodes?.length) return graph;
  const now = Date.now();
  const tool = String(event.name || '');
  const result = event.result || {};
  const inspect = graph.nodes[0]; const execute = graph.nodes[1]; const verify = graph.nodes[2];
  const readTools = /^(?:list_directory|file_glob_search|read_file|read_many_files|grep_search|get_info|find_symbol|find_references|project_intelligence|code_intelligence|browser_get_state|browser_inspect|browser_console|browser_snapshot|browser_wait|git_status|git_diff)$/;
  const writeTools = /^(?:write_file|edit_file|replace_in_file|create_artifact|update_artifact|create_document|update_document|worktree)$/;
  if (readTools.test(tool)) {
    inspect.status = result.error ? 'active' : 'done';
    if (!result.error) inspect.evidence.push({ tool, at: now });
  }
  if (writeTools.test(tool)) {
    if (inspect.status === 'pending') inspect.status = 'done';
    execute.status = result.error || result.status === 'denied' ? 'active' : 'done';
    if (!result.error && result.status !== 'denied') execute.evidence.push({ tool, path: event.args?.path || '', at: now });
  }
  if (/^(?:verify_project|git_diff|browser_snapshot|browser_console|browser_wait|worktree)$/.test(tool)) {
    if (execute.status === 'pending') execute.status = 'done';
    const ok = result.ok !== false && result.status !== 'failed' && !result.error;
    verify.status = ok ? 'done' : 'active';
    verify.evidence.push({ tool, ok, at: now });
  }
  graph.updatedAt = now;
  return graph;
}

export function graphRecoveryBlock(graph) {
  if (!graph?.nodes?.length) return '';
  return `Task graph:\n${graph.nodes.map((node) => `- ${node.status === 'done' ? '[done]' : node.status === 'active' ? '[active]' : '[pending]'} ${node.label}`).join('\n')}`;
}
