const DB_NAME = 'blackriver.workspace.projects';
const DB_VERSION = 1;
const PROJECTS_STORE = 'projects';
const META_STORE = 'meta';
const ACTIVE_KEY = 'activeProjectId';

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function requestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('IndexedDB request failed.'));
  });
}

function transactionDone(tx) {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error || new Error('IndexedDB transaction failed.'));
    tx.onabort = () => reject(tx.error || new Error('IndexedDB transaction aborted.'));
  });
}

function sanitizeCheckpoint(raw = {}) {
  return {
    id: String(raw.id || uid()),
    conversationId: String(raw.conversationId || ''),
    label: String(raw.label || 'Work session').slice(0, 160),
    files: Array.isArray(raw.files) ? raw.files.slice(0, 120).map((entry) => ({
      path: String(entry?.path || ''),
      before: typeof entry?.before === 'string' ? entry.before : null,
      status: ['added', 'modified', 'deleted'].includes(entry?.status) ? entry.status : 'modified',
    })).filter((entry) => entry.path) : [],
    createdAt: Number(raw.createdAt) || Date.now(),
    completedAt: Number(raw.completedAt) || 0,
  };
}

function sanitizeProject(raw = {}) {
  return {
    id: String(raw.id || uid()),
    name: String(raw.name || raw.handle?.name || 'Project').slice(0, 120),
    handle: raw.handle || null,
    nativePath: typeof raw.nativePath === 'string' ? raw.nativePath : '',
    instructions: String(raw.instructions || ''),
    pinnedContext: Array.isArray(raw.pinnedContext) ? raw.pinnedContext.map(String).filter(Boolean).slice(0, 64) : [],
    recentFiles: Array.isArray(raw.recentFiles) ? raw.recentFiles.map(String).filter(Boolean).slice(0, 40) : [],
    fileIndex: Array.isArray(raw.fileIndex) ? raw.fileIndex.slice(0, 700).map((entry) => ({
      path: String(entry?.path || ''),
      kind: entry?.kind === 'directory' ? 'directory' : 'file',
    })).filter((entry) => entry.path) : [],
    lastScannedAt: Number(raw.lastScannedAt) || 0,
    changedFiles: Array.isArray(raw.changedFiles) ? raw.changedFiles.slice(0, 120).map((entry) => ({
      path: String(entry?.path || ''),
      status: ['added', 'modified', 'deleted'].includes(entry?.status) ? entry.status : 'modified',
      before: typeof entry?.before === 'string' ? entry.before : null,
      after: typeof entry?.after === 'string' ? entry.after : null,
      checkpointId: String(entry?.checkpointId || ''),
      updatedAt: Number(entry?.updatedAt) || Date.now(),
    })).filter((entry) => entry.path) : [],
    checkpoints: Array.isArray(raw.checkpoints) ? raw.checkpoints.map(sanitizeCheckpoint).filter((entry) => entry.files.length).slice(0, 30) : [],
    createdAt: Number(raw.createdAt) || Date.now(),
    updatedAt: Number(raw.updatedAt) || Date.now(),
    lastOpenedAt: Number(raw.lastOpenedAt) || Date.now(),
  };
}

export class ProjectStore extends EventTarget {
  constructor() {
    super();
    this.db = null;
    this.projects = [];
    this.activeProjectId = null;
    this.ready = false;
    this.persistence = 'indexeddb';
  }

  async init() {
    if (this.ready) return this;
    if (!('indexedDB' in window)) {
      this.persistence = 'memory';
      this.ready = true;
      return this;
    }
    try {
      this.db = await new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = () => {
          const db = request.result;
          if (!db.objectStoreNames.contains(PROJECTS_STORE)) db.createObjectStore(PROJECTS_STORE, { keyPath: 'id' });
          if (!db.objectStoreNames.contains(META_STORE)) db.createObjectStore(META_STORE, { keyPath: 'key' });
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error('Could not open project database.'));
      });
      const tx = this.db.transaction([PROJECTS_STORE, META_STORE], 'readonly');
      const done = transactionDone(tx);
      const [projects, active] = await Promise.all([
        requestResult(tx.objectStore(PROJECTS_STORE).getAll()),
        requestResult(tx.objectStore(META_STORE).get(ACTIVE_KEY)),
      ]);
      await done;
      this.projects = projects.map(sanitizeProject).sort((a, b) => b.lastOpenedAt - a.lastOpenedAt);
      const hasPersistedActive = !!active && Object.prototype.hasOwnProperty.call(active, 'value');
      this.activeProjectId = hasPersistedActive && this.projects.some((p) => p.id === active.value) ? active.value : null;
    } catch (error) {
      console.warn('[BlackRiver Projects] IndexedDB unavailable; projects remain session-only.', error);
      this.persistence = 'memory';
    }
    this.ready = true;
    this.dispatchEvent(new Event('change'));
    return this;
  }

  list() { return [...this.projects].sort((a, b) => b.lastOpenedAt - a.lastOpenedAt); }
  get(id) { return this.projects.find((project) => project.id === id) || null; }
  get active() { return this.get(this.activeProjectId); }

  async persistProject(project) {
    if (!this.db) return;
    try {
      const tx = this.db.transaction(PROJECTS_STORE, 'readwrite');
      tx.objectStore(PROJECTS_STORE).put(project);
      await transactionDone(tx);
    } catch (error) {
      this.persistence = 'memory';
      console.warn('[BlackRiver Projects] project metadata could not be persisted; using session memory.', error);
    }
  }

  async persistActive() {
    if (!this.db) return;
    const tx = this.db.transaction(META_STORE, 'readwrite');
    tx.objectStore(META_STORE).put({ key: ACTIVE_KEY, value: this.activeProjectId });
    await transactionDone(tx);
  }

  async addHandle(handle) {
    const existing = this.projects.find((project) => project.name === handle?.name && project.handle?.isSameEntry);
    if (existing) {
      try {
        if (await existing.handle.isSameEntry(handle)) {
          existing.handle = handle;
          existing.nativePath = '';
          existing.lastOpenedAt = Date.now();
          existing.updatedAt = Date.now();
          this.activeProjectId = existing.id;
          await this.persistProject(existing);
          await this.persistActive();
          this.dispatchEvent(new Event('change'));
          return existing;
        }
      } catch {}
    }
    const project = sanitizeProject({ id: uid(), name: handle?.name || 'Project', handle });
    this.projects.unshift(project);
    this.activeProjectId = project.id;
    await this.persistProject(project);
    await this.persistActive();
    this.dispatchEvent(new Event('change'));
    return project;
  }

  async addNativePath(path, name = '') {
    const nativePath = String(path || '');
    if (!nativePath) throw new Error('Native project path is empty.');
    let project = this.projects.find((item) => item.nativePath && item.nativePath.toLowerCase() === nativePath.toLowerCase());
    if (project) {
      project.name = String(name || project.name || 'Project').slice(0, 120);
      project.lastOpenedAt = Date.now();
      project.updatedAt = Date.now();
    } else {
      project = sanitizeProject({ id: uid(), name: name || nativePath.split(/[\\/]/).filter(Boolean).at(-1) || 'Project', nativePath });
      this.projects.unshift(project);
    }
    this.activeProjectId = project.id;
    await this.persistProject(project);
    await this.persistActive();
    this.dispatchEvent(new Event('change'));
    return project;
  }

  async activate(id) {
    const project = this.get(id);
    if (!project) return null;
    this.activeProjectId = project.id;
    project.lastOpenedAt = Date.now();
    project.updatedAt = Date.now();
    await this.persistProject(project);
    await this.persistActive();
    this.dispatchEvent(new Event('change'));
    return project;
  }

  async remove(id) {
    const index = this.projects.findIndex((project) => project.id === id);
    if (index < 0) return false;
    this.projects.splice(index, 1);
    if (this.db) {
      const tx = this.db.transaction(PROJECTS_STORE, 'readwrite');
      tx.objectStore(PROJECTS_STORE).delete(id);
      await transactionDone(tx);
    }
    if (this.activeProjectId === id) this.activeProjectId = this.projects[0]?.id || null;
    await this.persistActive();
    this.dispatchEvent(new Event('change'));
    return true;
  }

  async deactivate() {
    this.activeProjectId = null;
    await this.persistActive();
    this.dispatchEvent(new Event('change'));
  }

  async noteFileIndex(id, entries = []) {
    const project = this.get(id);
    if (!project) return;
    project.fileIndex = Array.isArray(entries) ? entries.slice(0, 700).map((entry) => ({
      path: String(entry?.path || ''),
      kind: entry?.kind === 'directory' ? 'directory' : 'file',
    })).filter((entry) => entry.path) : [];
    project.lastScannedAt = Date.now();
    project.updatedAt = Date.now();
    await this.persistProject(project);
    this.dispatchEvent(new CustomEvent('project-meta', { detail: { id, kind: 'file-index', count: project.fileIndex.length } }));
  }

  async patch(id, patch = {}) {
    const project = this.get(id);
    if (!project) return null;
    if (patch.name !== undefined) project.name = String(patch.name || project.name).trim().slice(0, 120) || project.name;
    if (patch.instructions !== undefined) project.instructions = String(patch.instructions || '');
    if (patch.pinnedContext !== undefined) project.pinnedContext = Array.isArray(patch.pinnedContext)
      ? patch.pinnedContext.map(String).map((v) => v.trim()).filter(Boolean).slice(0, 64)
      : project.pinnedContext;
    project.updatedAt = Date.now();
    await this.persistProject(project);
    this.dispatchEvent(new Event('change'));
    return project;
  }

  async noteRecentFile(id, path) {
    const project = this.get(id);
    const clean = String(path || '').replace(/\\/g, '/').replace(/^\.\//, '');
    if (!project || !clean) return;
    project.recentFiles = [clean, ...project.recentFiles.filter((item) => item !== clean)].slice(0, 40);
    project.updatedAt = Date.now();
    await this.persistProject(project);
    this.dispatchEvent(new CustomEvent('project-meta', { detail: { id, kind: 'recent-file', path: clean } }));
  }

  async beginCheckpoint(id, { checkpointId = uid(), conversationId = '', label = 'Work session' } = {}) {
    const project = this.get(id);
    if (!project) return null;
    let checkpoint = project.checkpoints.find((entry) => entry.id === checkpointId);
    if (!checkpoint) {
      checkpoint = sanitizeCheckpoint({ id: checkpointId, conversationId, label, files: [] });
      project.checkpoints.unshift(checkpoint);
      project.checkpoints = project.checkpoints.slice(0, 30);
      await this.persistProject(project);
    }
    return checkpoint;
  }

  async noteChange(id, { path, before = null, after = null, status = 'modified', checkpointId = '', conversationId = '', checkpointLabel = 'Work session' } = {}) {
    const project = this.get(id);
    const clean = String(path || '').replace(/\\/g, '/').replace(/^\.\//, '');
    if (!project || !clean) return;
    const existing = project.changedFiles.find((item) => item.path === clean);
    const entry = {
      path: clean,
      status: ['added', 'modified', 'deleted'].includes(status) ? status : 'modified',
      before: existing?.before ?? (typeof before === 'string' ? before : null),
      after: typeof after === 'string' ? after : existing?.after ?? null,
      checkpointId: String(checkpointId || existing?.checkpointId || ''),
      updatedAt: Date.now(),
    };
    project.changedFiles = [entry, ...project.changedFiles.filter((item) => item.path !== clean)].slice(0, 120);

    if (checkpointId) {
      const checkpoint = await this.beginCheckpoint(id, { checkpointId, conversationId, label: checkpointLabel });
      if (checkpoint && !checkpoint.files.some((item) => item.path === clean)) {
        checkpoint.files.push({ path: clean, before: typeof before === 'string' ? before : null, status: entry.status });
      }
    }
    project.recentFiles = [clean, ...project.recentFiles.filter((item) => item !== clean)].slice(0, 40);
    project.updatedAt = Date.now();
    await this.persistProject(project);
    this.dispatchEvent(new CustomEvent('project-meta', { detail: { id, kind: 'changed-file', path: clean } }));
  }

  async completeCheckpoint(id, checkpointId) {
    const project = this.get(id);
    const checkpoint = project?.checkpoints.find((entry) => entry.id === checkpointId);
    if (!checkpoint) return null;
    if (!checkpoint.files.length) {
      project.checkpoints = project.checkpoints.filter((entry) => entry.id !== checkpointId);
    } else checkpoint.completedAt = Date.now();
    await this.persistProject(project);
    this.dispatchEvent(new Event('change'));
    return checkpoint;
  }

  latestCheckpoint(id) {
    return this.get(id)?.checkpoints?.find((entry) => entry.files?.length) || null;
  }

  async removeCheckpoint(id, checkpointId) {
    const project = this.get(id);
    if (!project) return;
    project.checkpoints = project.checkpoints.filter((entry) => entry.id !== checkpointId);
    await this.persistProject(project);
    this.dispatchEvent(new Event('change'));
  }

  async clearChanges(id) {
    const project = this.get(id);
    if (!project) return;
    project.changedFiles = [];
    project.updatedAt = Date.now();
    await this.persistProject(project);
    this.dispatchEvent(new Event('change'));
  }
}
