import { ProjectStore } from '../projects/project-store.js';
import { nativeAvailable, nativeCore } from '../native/native-bridge.js';
import { detectVerificationPlan, verificationSummary } from './verification-engine.js';

function normalizePath(path = '') {
  const parts = String(path || '').replace(/\\/g, '/').split('/').filter((part) => part && part !== '.');
  if (parts.some((part) => part === '..')) throw new Error('Project paths cannot escape the selected folder.');
  return parts;
}

async function resolveHandle(root, path, { createDir = false } = {}) {
  const parts = normalizePath(path);
  if (!parts.length) return { dir: root, name: '' };
  const name = parts.pop();
  let dir = root;
  for (const part of parts) dir = await dir.getDirectoryHandle(part, { create: createDir });
  return { dir, name };
}

async function readFile(root, path) {
  const { dir, name } = await resolveHandle(root, path);
  const handle = await dir.getFileHandle(name);
  return (await handle.getFile()).text();
}

async function fileExists(root, path) {
  try { const { dir, name } = await resolveHandle(root, path); await dir.getFileHandle(name); return true; } catch { return false; }
}

async function writeTextFile(root, path, content) {
  const { dir, name } = await resolveHandle(root, path, { createDir: true });
  const handle = await dir.getFileHandle(name, { create: true });
  const writable = await handle.createWritable();
  await writable.write(String(content ?? ''));
  await writable.close();
}

async function walk(dir, prefix = '', depth = 0, maxDepth = 6, out = [], maxEntries = 700) {
  if (depth > maxDepth || out.length >= maxEntries) return out;
  for await (const [name, handle] of dir.entries()) {
    if (out.length >= maxEntries) break;
    if (handle.kind === 'directory' && ['.git', 'node_modules', 'dist', 'build', '.next', '.cache', '.venv', 'venv', '__pycache__'].includes(name)) continue;
    const path = prefix ? `${prefix}/${name}` : name;
    out.push({ path, kind: handle.kind });
    if (handle.kind === 'directory') await walk(handle, path, depth + 1, maxDepth, out, maxEntries);
  }
  return out;
}

function globToRegExp(glob = '**/*') {
  const escaped = String(glob).replace(/\\/g, '/').replace(/^\.\//, '').replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*\*/g, '§§DOUBLESTAR§§').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]').replace(/§§DOUBLESTAR§§/g, '.*');
  return new RegExp(`^${escaped}$`, 'i');
}

function isNativeRecord(record) {
  return !!record?.nativePath && nativeAvailable() && !!nativeCore()?.projectCall;
}

function nativeRoot(record) {
  return isNativeRecord(record) ? { kind: 'native', path: record.nativePath } : null;
}

export class ProjectWorkspace extends EventTarget {
  constructor(store = new ProjectStore()) {
    super();
    this.store = store;
    this.root = null;
    this.name = null;
    this.id = null;
    this.permission = 'none';
    this.store.addEventListener('change', () => this.dispatchEvent(new CustomEvent('projects', { detail: { projects: this.projects, activeId: this.id } })));
  }

  get available() { return !!nativeCore()?.pickProjectDirectory || typeof window.showDirectoryPicker === 'function'; }
  get projects() { return this.store.list(); }
  get activeProject() { return this.store.get(this.id) || null; }
  get instructions() { return this.activeProject?.instructions || ''; }
  get pinnedContext() { return this.activeProject?.pinnedContext || []; }
  get changedFiles() { return this.activeProject?.changedFiles || []; }
  get recentFiles() { return this.activeProject?.recentFiles || []; }
  get fileIndex() { return this.activeProject?.fileIndex || []; }
  get isNative() { return isNativeRecord(this.activeProject); }

  async init() { await this.store.init(); return this; }

  async ensurePermission(handle, { request = true } = {}) {
    if (!handle) return 'denied';
    const options = { mode: 'readwrite' };
    try {
      let state = await handle.queryPermission?.(options) || 'prompt';
      if (state !== 'granted' && request) state = await handle.requestPermission?.(options) || state;
      return state;
    } catch { return 'prompt'; }
  }

  async chooseDirectory() {
    if (nativeAvailable() && nativeCore()?.pickProjectDirectory) {
      const picked = await nativeCore().pickProjectDirectory();
      if (!picked?.path) throw new DOMException('Project selection cancelled.', 'AbortError');
      const record = await this.store.addNativePath(picked.path, picked.name);
      await this.activate(record.id, { requestPermission: false });
      return this.root;
    }
    if (typeof window.showDirectoryPicker !== 'function') throw new Error('This browser does not expose editable project folders. Use BlackRiver Desktop or a Chromium browser.');
    const handle = await window.showDirectoryPicker({ mode: 'readwrite' });
    const record = await this.store.addHandle(handle);
    await this.activate(record.id, { requestPermission: true });
    return this.root;
  }

  async activate(id, { requestPermission = true, quiet = false } = {}) {
    const record = await this.store.activate(id);
    if (!record) return null;
    this.id = record.id;
    this.name = record.name;
    if (isNativeRecord(record)) {
      this.permission = 'granted';
      this.root = nativeRoot(record);
    } else {
      this.permission = await this.ensurePermission(record.handle, { request: requestPermission });
      this.root = this.permission === 'granted' ? record.handle : null;
    }
    if (this.root) { try { await this.refreshFileIndex(record.id, { root: this.root }); } catch {} }
    if (!quiet) this.dispatchEvent(new CustomEvent('project', { detail: { id: this.id, name: this.name, permission: this.permission, native: this.isNative } }));
    return record;
  }

  async removeProject(id) {
    const wasActive = id === this.id;
    await this.store.remove(id);
    if (wasActive) {
      this.root = null; this.name = null; this.id = null; this.permission = 'none';
      if (this.store.activeProjectId) await this.activate(this.store.activeProjectId, { requestPermission: false, quiet: true });
      this.dispatchEvent(new CustomEvent('project', { detail: { id: this.id, name: this.name, permission: this.permission, native: this.isNative } }));
    }
  }

  async updateProject(patch) {
    if (!this.id) return null;
    const record = await this.store.patch(this.id, patch);
    if (record) this.name = record.name;
    this.dispatchEvent(new CustomEvent('project', { detail: { id: this.id, name: this.name, permission: this.permission, native: this.isNative } }));
    return record;
  }

  async clearChanges() { if (this.id) await this.store.clearChanges(this.id); }

  async deactivate({ quiet = false } = {}) {
    await this.store.deactivate();
    this.root = null; this.name = null; this.id = null; this.permission = 'none';
    if (!quiet) this.dispatchEvent(new CustomEvent('project', { detail: { id: null, name: null, permission: 'none', native: false } }));
  }

  clear() {
    this.root = null; this.name = null; this.id = null; this.permission = 'none';
    this.store.deactivate().catch(() => {});
    this.dispatchEvent(new CustomEvent('project', { detail: { id: null, name: null, permission: 'none', native: false } }));
  }

  async rootForProject(projectId = this.id, { requestPermission = false } = {}) {
    const record = this.store.get(projectId);
    if (!record) return null;
    if (isNativeRecord(record)) return nativeRoot(record);
    if (projectId === this.id && this.root) return this.root;
    const permission = await this.ensurePermission(record.handle, { request: requestPermission });
    return permission === 'granted' ? record.handle : null;
  }

  async refreshFileIndex(projectId = this.id, { root = null, maxDepth = 5, maxEntries = 500 } = {}) {
    if (!projectId) return [];
    const record = this.store.get(projectId);
    const handle = root || await this.rootForProject(projectId, { requestPermission: false });
    if (!handle) return record?.fileIndex || [];
    let entries;
    if (isNativeRecord(record)) {
      const result = await nativeCore().projectCall({ action: 'scan', rootPath: record.nativePath, maxDepth, maxEntries });
      entries = result?.entries || [];
    } else entries = await walk(handle, '', 0, maxDepth, [], maxEntries);
    await this.store.noteFileIndex(projectId, entries);
    return entries;
  }

  async projectSnapshot(projectId = this.id, { refresh = true, maxEntries = 160 } = {}) {
    const record = this.store.get(projectId);
    if (!record) return null;
    let entries = record.fileIndex || [];
    if (refresh) { try { entries = await this.refreshFileIndex(projectId, { maxDepth: 5, maxEntries: Math.max(maxEntries, 240) }); } catch {} }
    const files = entries.filter((entry) => entry.kind === 'file').slice(0, maxEntries).map((entry) => entry.path);
    const directories = entries.filter((entry) => entry.kind === 'directory').slice(0, 64).map((entry) => entry.path);
    return { id: record.id, name: record.name, nativePath: record.nativePath || '', files, directories, indexedCount: entries.length, lastScannedAt: record.lastScannedAt || 0, recentFiles: record.recentFiles || [], changedFiles: record.changedFiles || [] };
  }

  requireRoot() {
    if (!this.id) throw new Error('No Work project is active.');
    if (!this.root) throw new Error(`Project “${this.name}” needs filesystem permission. Open Projects and reconnect it.`);
    return this.root;
  }

  get definitions() { return this.definitionsForProject(this.id); }

  definitionsForProject(projectId = this.id) {
    const record = this.store.get(projectId);
    const available = !!record && ((projectId === this.id && !!this.root) || isNativeRecord(record) || !!record.handle);
    if (!available) return [];
    const base = [
      { type: 'function', function: { name: 'list_directory', description: 'List files and folders inside the active project. Use this early when exploring an unfamiliar project.', parameters: { type: 'object', properties: { path: { type: 'string', description: 'Project-relative directory. Empty string means project root.' } } } } },
      { type: 'function', function: { name: 'file_glob_search', description: 'Find files in the active project by glob pattern. Examples: **/*.js, src/**/*.ts, *.html.', parameters: { type: 'object', properties: { pattern: { type: 'string' }, max_results: { type: 'number' } }, required: ['pattern'] } } },
      { type: 'function', function: { name: 'read_file', description: 'Read one UTF-8 text file from the active project.', parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } } },
      { type: 'function', function: { name: 'read_many_files', description: 'Read several project text files in parallel. Prefer this over serial read_file calls when multiple known files are needed.', parameters: { type: 'object', properties: { paths: { type: 'array', items: { type: 'string' } } }, required: ['paths'] } } },
      { type: 'function', function: { name: 'grep_search', description: 'Search project text files for a literal query and return matching lines.', parameters: { type: 'object', properties: { query: { type: 'string' }, path: { type: 'string' }, max_results: { type: 'number' } }, required: ['query'] } } },
      { type: 'function', function: { name: 'write_file', description: 'Create or overwrite a UTF-8 file. User approval is required. BlackRiver checkpoints the original for Undo.', parameters: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] } } },
      { type: 'function', function: { name: 'edit_file', description: 'Edit a file by replacing exact text. User approval is required and the original is checkpointed.', parameters: { type: 'object', properties: { path: { type: 'string' }, search: { type: 'string' }, replace: { type: 'string' }, replace_all: { type: 'boolean' } }, required: ['path', 'search', 'replace'] } } },
      { type: 'function', function: { name: 'get_info', description: 'Return active project metadata, current changes, and Work capabilities.', parameters: { type: 'object', properties: {} } } },
    ];
    if (isNativeRecord(record)) base.push(
      { type: 'function', function: { name: 'run_command', description: 'Run a non-mutating verification/diagnostic command inside the active native project, such as a build, test, lint, or status command. Do not use shell commands to edit/delete source files; use write_file/edit_file so changes are checkpointed. Requires user approval.', parameters: { type: 'object', properties: { command: { type: 'string' }, timeout_ms: { type: 'number' } }, required: ['command'] } } },
      { type: 'function', function: { name: 'git_status', description: 'Read git status for the active native project.', parameters: { type: 'object', properties: {} } } },
      { type: 'function', function: { name: 'git_diff', description: 'Read git diff for the active native project or one project-relative path.', parameters: { type: 'object', properties: { path: { type: 'string' }, staged: { type: 'boolean' } } } } },
      { type: 'function', function: { name: 'verify_project', description: "Run BlackRiver's stack-aware verification plan for the active native project (build/tests/lint when detected). Prefer this before declaring a coding task complete. Requires one approval for the detected commands.", parameters: { type: 'object', properties: { max_checks: { type: 'number' } } } } },
      { type: 'function', function: { name: 'terminal_session', description: 'Control a persistent project terminal for dev servers, watchers, REPLs, or long-running test processes. Use run_command for ordinary one-shot verification. Source edits still belong in write_file/edit_file.', parameters: { type: 'object', properties: { action: { type: 'string', enum: ['start','read','write','stop','list'] }, id: { type: 'string' }, command: { type: 'string' }, data: { type: 'string' }, cursor: { type: 'number' } }, required: ['action'] } } },
      { type: 'function', function: { name: 'worktree', description: 'Use an isolated BlackRiver Git worktree for parallel/alternative implementation without touching the primary project tree. This is an advanced internal tool; use it only when isolation materially helps.', parameters: { type: 'object', properties: { action: { type: 'string', enum: ['list','create','read','write','edit','run','diff','status','remove'] }, id: { type: 'string' }, label: { type: 'string' }, base: { type: 'string' }, path: { type: 'string' }, content: { type: 'string' }, search: { type: 'string' }, replace: { type: 'string' }, replace_all: { type: 'boolean' }, command: { type: 'string' }, timeout_ms: { type: 'number' }, force: { type: 'boolean' } }, required: ['action'] } } },
      { type: 'function', function: { name: 'code_intelligence', description: 'Query BlackRiver Project Intelligence. It uses a real LSP when a compatible language server is installed and falls back to the built-in symbol/reference index automatically.', parameters: { type: 'object', properties: { action: { type: 'string', enum: ['symbol','definition','references','outline','hover'] }, query: { type: 'string' }, path: { type: 'string' }, scope: { type: 'string' }, line: { type: 'number' }, character: { type: 'number' }, backend: { type: 'string', enum: ['auto','lsp','static'] }, max_results: { type: 'number' } }, required: ['action'] } } },
    );
    return base;
  }

  async browserReadMany(root, paths) {
    return Promise.all(paths.slice(0, 24).map(async (path) => {
      try { return { path, content: await readFile(root, path) }; } catch (error) { return { path, error: error?.message || String(error) }; }
    }));
  }

  async execute(name, args = {}, { approve, projectId: requestedProjectId, checkpointId = '', conversationId = '', checkpointLabel = 'Work session' } = {}) {
    const projectId = requestedProjectId !== undefined ? requestedProjectId : this.id;
    const record = this.store.get(projectId);
    if (!record) throw new Error('The Work project for this generation is no longer available.');
    const root = await this.rootForProject(projectId, { requestPermission: false });
    if (!root) throw new Error(`Project “${record.name}” is not currently authorized. Reopen it from Projects and retry.`);
    const native = isNativeRecord(record);
    const callNative = (action, payload = {}) => nativeCore().projectCall({ action, rootPath: record.nativePath, ...payload });

    switch (name) {
      case 'get_info':
      {
        const capabilities = ['list_directory', 'file_glob_search', 'read_file', 'read_many_files', 'grep_search', 'write_file', 'edit_file', 'get_info'];
        if (native) capabilities.push('run_command', 'git_status', 'git_diff', 'verify_project', 'terminal_session', 'worktree', 'code_intelligence');
        return { project_id: projectId, project: record.name, root_access: native ? 'native-desktop' : 'browser-granted', native_path: native ? record.nativePath : '', instructions: record.instructions || '', pinned_context: record.pinnedContext || [], indexed_files: (record.fileIndex || []).filter((entry) => entry.kind === 'file').slice(0, 160).map((entry) => entry.path), recent_files: (record.recentFiles || []).slice(0, 16), changed_files: (record.changedFiles || []).map(({ path, status }) => ({ path, status })), capabilities, shell: native, git: native };
      }
      case 'file_glob_search': {
        if (native) return callNative('glob', { pattern: args.pattern, maxResults: args.max_results });
        const all = await walk(root, '', 0, 8, [], 700); const pattern = String(args.pattern || '**/*').replace(/\\/g, '/').replace(/^\.\//, ''); const regex = globToRegExp(pattern); const limit = Math.max(1, Math.min(Number(args.max_results) || 200, 500)); const matches = all.filter((entry) => entry.kind === 'file' && regex.test(entry.path)).slice(0, limit).map((entry) => entry.path); return { pattern, matches, truncated: matches.length >= limit };
      }
      case 'list_directory': {
        if (native) return callNative('list', { path: args.path || '' });
        let dir = root; for (const part of normalizePath(args.path || '')) dir = await dir.getDirectoryHandle(part); const entries = []; for await (const [entryName, handle] of dir.entries()) entries.push({ name: entryName, kind: handle.kind }); entries.sort((a, b) => a.kind === b.kind ? a.name.localeCompare(b.name) : a.kind === 'directory' ? -1 : 1); return { path: args.path || '.', entries };
      }
      case 'read_file': {
        const result = native ? await callNative('read', { path: args.path }) : { path: args.path, content: await readFile(root, args.path) };
        await this.store.noteRecentFile(projectId, args.path); return result;
      }
      case 'read_many_files': {
        const paths = Array.isArray(args.paths) ? args.paths.map(String).filter(Boolean).slice(0, 24) : [];
        const result = native ? await callNative('read-many', { paths }) : { files: await this.browserReadMany(root, paths) };
        for (const file of result.files || []) if (!file.error) await this.store.noteRecentFile(projectId, file.path);
        return result;
      }
      case 'grep_search': {
        if (native) return callNative('grep', { query: args.query, path: args.path || '', maxResults: args.max_results });
        const all = await walk(root, '', 0, 7, [], 700); const prefix = (args.path || '').replace(/\\/g, '/').replace(/^\/|\/$/g, ''); const query = String(args.query || ''); const limit = Math.max(1, Math.min(Number(args.max_results) || 50, 200)); const matches = []; const textExt = /\.(txt|md|js|mjs|cjs|ts|tsx|jsx|json|html|css|scss|py|rs|cpp|c|h|hpp|java|go|toml|yaml|yml|ini|bat|ps1|sh|xml|svg)$/i;
        for (const entry of all) { if (matches.length >= limit) break; if (entry.kind !== 'file' || !textExt.test(entry.path) || (prefix && !entry.path.startsWith(prefix))) continue; try { const content = await readFile(root, entry.path); content.split(/\r?\n/).forEach((line, index) => { if (matches.length < limit && line.includes(query)) matches.push({ path: entry.path, line: index + 1, text: line.slice(0, 600) }); }); } catch {} }
        return { query, matches, truncated: matches.length >= limit };
      }
      case 'write_file': {
        let existed; let before;
        if (native) {
          const check = await callNative('exists', { path: args.path }); existed = !!check.exists; before = existed ? (await callNative('read', { path: args.path })).content : null;
        } else { existed = await fileExists(root, args.path); before = existed ? await readFile(root, args.path) : null; }
        const after = String(args.content ?? '');
        const ok = await approve?.({ name, args: { path: args.path }, summary: `${existed ? 'Write' : 'Create'} ${args.path}`, before, after });
        if (ok === false) return { status: 'denied', path: args.path };
        if (native) await callNative('write', { path: args.path, content: after }); else await writeTextFile(root, args.path, after);
        await this.store.noteChange(projectId, { path: args.path, before, after, status: existed ? 'modified' : 'added', checkpointId, conversationId, checkpointLabel });
        await this.refreshFileIndex(projectId, { root, maxDepth: 5, maxEntries: 500 });
        return { status: 'ok', path: args.path, bytes: new Blob([after]).size, change: existed ? 'modified' : 'added', checkpoint_id: checkpointId || null };
      }
      case 'edit_file':
      case 'replace_in_file': {
        const before = native ? (await callNative('read', { path: args.path })).content : await readFile(root, args.path);
        const search = String(args.search ?? ''); if (!search) throw new Error('Search text cannot be empty.');
        const count = before.split(search).length - 1; if (!count) return { status: 'not_found', path: args.path, occurrences: 0 };
        const after = args.replace_all ? before.split(search).join(String(args.replace ?? '')) : before.replace(search, String(args.replace ?? ''));
        const ok = await approve?.({ name, args: { path: args.path, replace_all: !!args.replace_all }, summary: `Edit ${args.path} (${args.replace_all ? count : 1} replacement${count === 1 ? '' : 's'})`, before, after });
        if (ok === false) return { status: 'denied', path: args.path };
        if (native) await callNative('write', { path: args.path, content: after }); else await writeTextFile(root, args.path, after);
        await this.store.noteChange(projectId, { path: args.path, before, after, status: 'modified', checkpointId, conversationId, checkpointLabel });
        await this.refreshFileIndex(projectId, { root, maxDepth: 5, maxEntries: 500 });
        return { status: 'ok', path: args.path, occurrences: args.replace_all ? count : 1, change: 'modified', checkpoint_id: checkpointId || null };
      }
      case 'run_command': {
        if (!native) throw new Error('Shell commands are available only in BlackRiver Desktop native projects.');
        const command = String(args.command || '').trim();
        const ok = await approve?.({ name, args: { command }, summary: `Run command in ${record.name}:\n${command}` });
        if (ok === false) return { status: 'denied', command };
        const result = await callNative('command', { command, timeoutMs: args.timeout_ms });
        return { command, ...result, ok: result.code === 0 && !result.timedOut };
      }
      case 'terminal_session': {
        if (!native) throw new Error('Persistent terminal sessions are available only in BlackRiver Desktop native projects.');
        const action = String(args.action || 'list');
        if (['start', 'write', 'stop'].includes(action)) {
          const summary = action === 'start' ? `Start project terminal:
${String(args.command || '').trim()}` : action === 'write' ? `Send input to terminal ${args.id || ''}` : `Stop terminal ${args.id || ''}`;
          const ok = await approve?.({ name, args: { ...args, data: action === 'write' ? String(args.data || '').slice(0, 240) : args.data }, summary });
          if (ok === false) return { status: 'denied', action, id: args.id || '' };
        }
        return callNative('terminal', { op: action, id: args.id, command: args.command, data: args.data, cursor: args.cursor });
      }
      case 'worktree': {
        if (!native) throw new Error('BlackRiver worktrees are available only in Desktop native Git projects.');
        const action = String(args.action || 'list');
        if (['create', 'write', 'edit', 'run', 'remove'].includes(action)) {
          const summary = action === 'create' ? `Create isolated Git worktree${args.label ? ` “${args.label}”` : ''}` : action === 'remove' ? `Remove isolated worktree ${args.id || ''}` : `${action[0].toUpperCase()}${action.slice(1)} in isolated worktree ${args.id || ''}${args.path ? ` · ${args.path}` : ''}`;
          const ok = await approve?.({ name, args, summary });
          if (ok === false) return { status: 'denied', action, id: args.id || '' };
        }
        return callNative('worktree', { op: action, id: args.id, label: args.label, base: args.base, path: args.path, content: args.content, search: args.search, replace: args.replace, replaceAll: !!args.replace_all, command: args.command, timeoutMs: args.timeout_ms, force: !!args.force });
      }
      case 'code_intelligence': {
        if (!native) throw new Error('Project Intelligence LSP/index tools are available only in BlackRiver Desktop native projects.');
        const hintPath = args.path || (record.fileIndex || []).find((entry) => entry.kind === 'file' && /\.(?:tsx?|jsx?|mjs|cjs|py|rs|go)$/i.test(entry.path))?.path || '';
        return callNative('code-intelligence', { op: args.action, query: args.query, path: args.path, scope: args.scope, line: args.line, character: args.character, backend: args.backend || 'auto', maxResults: args.max_results, hintPath });
      }
      case 'git_status': {
        if (!native) throw new Error('Git tools are available only in BlackRiver Desktop native projects.');
        const result = await callNative('git-status'); return { ...result, ok: result.code === 0 };
      }
      case 'git_diff': {
        if (!native) throw new Error('Git tools are available only in BlackRiver Desktop native projects.');
        const result = await callNative('git-diff', { path: args.path || '', staged: !!args.staged }); return { ...result, ok: result.code === 0 };
      }
      case 'verify_project': {
        if (!native) throw new Error('Automatic verification is available only in BlackRiver Desktop native projects.');
        const snapshot = await this.projectSnapshot(projectId, { refresh: false, maxEntries: 700 });
        const plan = detectVerificationPlan(snapshot || {}, { max: args.max_checks || 3 });
        if (!plan.length) return { status: 'no-plan', ok: true, plan: [], results: [], summary: 'No automatic verification command was detected.' };
        const ok = await approve?.({ name, args: { commands: plan.map((item) => item.command) }, summary: `Verify ${record.name}:\n${plan.map((item) => `• ${item.command}`).join('\n')}` });
        if (ok === false) return { status: 'denied', ok: false, plan, results: [], summary: 'Verification denied.' };
        const results = [];
        for (const check of plan) {
          const result = await callNative('command', { command: check.command, timeoutMs: 180000 });
          results.push({ ...check, ...result, ok: result.code === 0 && !result.timedOut });
          if (result.code !== 0 || result.timedOut) break;
        }
        return { status: results.every((item) => item.ok) ? 'passed' : 'failed', ok: results.length > 0 && results.every((item) => item.ok), plan, results, summary: verificationSummary(results) };
      }
      default: throw new Error(`Unknown Work tool: ${name}`);
    }
  }

  async revertChange(path) {
    const record = this.activeProject;
    const root = this.requireRoot();
    const entry = this.changedFiles.find((item) => item.path === path);
    if (!entry) throw new Error('Tracked change not found.');
    if (isNativeRecord(record)) {
      if (entry.status === 'added' && entry.before == null) await nativeCore().projectCall({ action: 'delete', rootPath: record.nativePath, path });
      else await nativeCore().projectCall({ action: 'write', rootPath: record.nativePath, path, content: entry.before ?? '' });
    } else if (entry.status === 'added' && entry.before == null) {
      const { dir, name } = await resolveHandle(root, path); await dir.removeEntry(name);
    } else await writeTextFile(root, path, entry.before ?? '');
    record.changedFiles = record.changedFiles.filter((item) => item.path !== path);
    await this.store.persistProject(record);
    await this.refreshFileIndex(this.id, { root, maxDepth: 5, maxEntries: 500 });
    this.store.dispatchEvent(new Event('change'));
    return true;
  }

  async undoCheckpoint(checkpointId = '') {
    const record = this.activeProject;
    if (!record) throw new Error('No active project.');
    const checkpoint = checkpointId ? record.checkpoints.find((item) => item.id === checkpointId) : this.store.latestCheckpoint(record.id);
    if (!checkpoint?.files?.length) throw new Error('No Work checkpoint is available to undo.');
    const root = this.requireRoot();
    for (const entry of [...checkpoint.files].reverse()) {
      if (isNativeRecord(record)) {
        if (entry.status === 'added' && entry.before == null) {
          try { await nativeCore().projectCall({ action: 'delete', rootPath: record.nativePath, path: entry.path }); } catch {}
        } else await nativeCore().projectCall({ action: 'write', rootPath: record.nativePath, path: entry.path, content: entry.before ?? '' });
      } else if (entry.status === 'added' && entry.before == null) {
        try { const { dir, name } = await resolveHandle(root, entry.path); await dir.removeEntry(name); } catch {}
      } else await writeTextFile(root, entry.path, entry.before ?? '');
      record.changedFiles = record.changedFiles.filter((item) => item.checkpointId !== checkpoint.id || item.path !== entry.path);
    }
    await this.store.removeCheckpoint(record.id, checkpoint.id);
    await this.store.persistProject(record);
    await this.refreshFileIndex(record.id, { root, maxDepth: 5, maxEntries: 500 });
    return checkpoint;
  }
}
