function safeJson(text) {
  const raw = String(text || '{}').trim();
  try { return JSON.parse(raw); } catch {}
  const unfenced = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const start = unfenced.indexOf('{');
  const end = unfenced.lastIndexOf('}');
  const objectish = start >= 0 && end > start ? unfenced.slice(start, end + 1) : unfenced;
  const repaired = objectish
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/([{,]\s*)([A-Za-z_$][\w$-]*)\s*:/g, '$1"$2":');
  try { return JSON.parse(repaired); } catch { return null; }
}

function detachVisionImage(result) {
  if (!result || typeof result !== 'object' || !result.__blackriverVisionImage) return { result, vision: null };
  const vision = result.__blackriverVisionImage;
  const clean = { ...result };
  delete clean.__blackriverVisionImage;
  return { result: clean, vision };
}

function visionFollowupMessage(vision, label = 'Browser Lab screenshot') {
  if (!vision?.data) return null;
  return { role: 'user', content: [{ type: 'image', data: vision.data, mime: vision.mime || 'image/png' }, { type: 'text', text: `${label}. Inspect the rendered result visually and use this evidence for the current task. Continue debugging or verification instead of merely describing the image.` }] };
}

function normalizeMetrics(chunk, contextSize = 0) {
  const timings = chunk?.timings || {};
  const usage = chunk?.usage || {};
  const progress = chunk?.prompt_progress || null;
  const promptTokens = Number(usage.prompt_tokens ?? ((timings.cache_n || 0) + (timings.prompt_n || 0))) || 0;
  const completionTokens = Number(usage.completion_tokens ?? timings.predicted_n) || 0;
  const used = Number(usage.total_tokens) || (promptTokens + completionTokens);
  const ctx = Number(contextSize) || 0;
  return {
    promptTokens,
    completionTokens,
    used,
    remaining: ctx ? Math.max(0, ctx - used) : 0,
    contextSize: ctx,
    cachedTokens: Number(timings.cache_n || usage.prompt_tokens_details?.cached_tokens) || 0,
    promptTps: Number(timings.prompt_per_second) || 0,
    generationTpsLive: Number(timings.predicted_per_second_3s) || 0,
    generationTpsAverage: Number(timings.predicted_per_second) || 0,
    generationTps: Number(timings.predicted_per_second_3s || timings.predicted_per_second) || 0,
    promptProgress: progress ? {
      total: Number(progress.total) || 0,
      cache: Number(progress.cache) || 0,
      processed: Number(progress.processed) || 0,
      timeMs: Number(progress.time_ms) || 0,
    } : null,
  };
}


function reasoningRequestOptions(profile = 'auto') {
  const effort = ['auto', 'off', 'low', 'medium', 'high'].includes(profile) ? profile : 'auto';
  // The harness expresses user intent only. Each runtime translates this into
  // the actual model/template dialect (llama.cpp reasoning_effort or budget
  // fallback, Ollama think levels, Codex supported efforts, etc.).
  return { blackriver_reasoning_profile: effort };
}

export class AgentHarness {
  constructor(runtime, project, artifacts, toolRegistry = null, skills = null, memory = null, crew = null, policy = null, hooks = null) {
    this.runtime = runtime;
    this.project = project;
    this.artifacts = artifacts;
    this.toolRegistry = toolRegistry;
    this.skills = skills;
    this.memory = memory;
    this.policy = policy;
    this.hooks = hooks;
    this.crew = crew || new AgentCrew(runtime);
    this.maxTurns = 20;
    this.hooks?.setExecutor?.((name, args, envelope) => this.executeTool(name, args, { ...(envelope?.context || {}), fromHook: true }));
  }

  toolDefinitions(mode, { prompt = '', conversationId = null, projectId = undefined } = {}) {
    const downloadDefs = this.artifacts.downloadDefinitions;
    const downloadIntent = downloadToolIntent(prompt);
    const documentNames = new Set(['create_document', 'update_document', 'read_document', 'create_document_bundle']);
    const memoryDefs = this.toolRegistry ? this.toolRegistry.definitions({ sourceIds: ['memory'], context: { mode, projectId } }) : (this.memory?.definitions || []);
    const browserDefs = this.toolRegistry ? this.toolRegistry.definitions({ sourceIds: ['browser'], context: { mode, projectId } }) : [];
    const memoryIntent = /\b(memory|remember|remember that|forget|forgot|recall|what do you remember|save this preference)\b/i.test(String(prompt || ''));

    if (mode === 'chat') {
      const chatMemory = memoryIntent ? memoryDefs : [];
      if (!downloadIntent.use) return chatMemory;
      let downloads;
      if (downloadIntent.document) {
        // Keep the full tiny document tool family available so one turn can make
        // multiple office files and package them without a second conversation.
        downloads = downloadDefs.filter((tool) => documentNames.has(tool.function?.name));
      } else if (downloadIntent.projectish && !downloadIntent.explicit) downloads = downloadDefs;
      else downloads = downloadDefs.filter((tool) => {
        const name = tool.function?.name;
        if (downloadIntent.zip) return name === 'create_zip_artifact';
        return name === 'create_downloadable_file';
      });
      return [...chatMemory, ...downloads];
    }
    if (mode !== 'work') return [];

    const resolvedProjectId = projectId !== undefined ? projectId : this.project.id;
    const projectRecord = resolvedProjectId ? this.project.store?.get(resolvedProjectId) : null;
    const hasProject = !!resolvedProjectId && ((resolvedProjectId === this.project.id && !!this.project.root) || !!projectRecord?.nativePath || !!projectRecord?.handle);
    const conversationArtifacts = this.artifacts.list(conversationId);
    const hasArtifacts = conversationArtifacts.some((item) => ['html', 'code', 'text', 'markdown', 'document'].includes(item.type));
    const intent = workToolIntent(prompt, { hasProject, hasArtifacts });
    const allPluginDefs = this.toolRegistry ? this.toolRegistry.definitions({ sourceIds: ['plugins'], context: { mode, projectId: resolvedProjectId } }) : [];
    const pluginGatewayDefs = this.toolRegistry?.gatewayDefinitions?.('plugins', { mode, projectId: resolvedProjectId }) || [];
    const relevantPluginDefs = selectRelevantPluginTools(allPluginDefs, prompt, { max: 6 });
    const pluginLikely = relevantPluginDefs.length > 0 || /\b(mcp|plugin|github|pull request|\bpr\b|issue|commit|branch|slack|calendar|email|gmail|search online|web search)\b/i.test(String(prompt || ''));
    const viewerDefs = this.artifacts.viewerDefinitions;
    const documentDefs = downloadDefs.filter((tool) => documentNames.has(tool.function?.name));
    const activeConversationArtifact = conversationArtifacts.find((item) => item.id === this.artifacts.lastTouchedId)
      || conversationArtifacts.find((item) => item.id === this.artifacts.activeId)
      || conversationArtifacts[0] || null;
    const documentContinuation = !!(intent.artifactContinuation && activeConversationArtifact?.type === 'document');
    const browserLikely = intent.artifact || activeConversationArtifact?.type === 'html' || /\b(browser|preview|render|visual|ui|click|button|input|console|runtime|screenshot|test|debug|layout|responsive)\b/i.test(String(prompt || ''));
    const projectDefs = hasProject ? (this.project.definitionsForProject?.(resolvedProjectId) || this.project.definitions) : [];

    // Codex app-server dynamic tools are fixed for the life of a persistent
    // thread. Expose BlackRiver's two-tool MCP gateway instead of dumping every
    // connected MCP schema into that thread. The gateway can discover/call any
    // connected plugin later without recreating the Codex thread.
    if (this.runtime.capabilities?.dynamicTools) {
      const stable = [...viewerDefs, ...downloadDefs, ...projectDefs, ...memoryDefs, ...browserDefs, ...(allPluginDefs.length ? pluginGatewayDefs : [])];
      const seen = new Set();
      return stable.filter((tool) => {
        const name = tool.function?.name;
        if (!name || seen.has(name)) return false;
        seen.add(name);
        return true;
      });
    }

    if (!hasProject && !hasArtifacts && !intent.useTools && !downloadIntent.explicit && !pluginLikely && !memoryIntent) return [];
    const tools = [];

    if (downloadIntent.document || documentContinuation) {
      // Keep generated PDF/Office documents editable as first-class artifacts.
      // A natural follow-up such as “make it more professional” should read and
      // update the same document source rather than starting a new file.
      tools.push(...documentDefs);
    } else if (downloadIntent.explicit) {
      tools.push(...downloadDefs.filter((tool) => downloadIntent.zip ? tool.function?.name === 'create_zip_artifact' : tool.function?.name === 'create_downloadable_file'));
    } else if (intent.artifact || (hasArtifacts && !intent.project)) {
      // Core Artifact tools remain available for the life of an Artifact-backed
      // Work conversation. Terse follow-ups such as “you die 1 sec after start”
      // must never force the model to rediscover built-ins through Plugins/MCP.
      tools.push(...viewerDefs);
      if (browserLikely || activeConversationArtifact?.type === 'html') tools.push(...browserDefs);
    }

    // Clear Artifact follow-ups should not expose filesystem tools just because a
    // project happens to be selected in the composer. This prevents Work from
    // forgetting the thing it just rendered and wandering into an unrelated root.
    if (intent.project) tools.push(...projectDefs);

    // Never hand llama.cpp a connected MCP server's full JSON-schema catalog.
    // The server log showed that this can explode into an enormous generated
    // grammar and fail before sampling starts. Expose only BlackRiver's compact
    // two-tool MCP gateway; it discovers/calls the relevant external tool at
    // runtime without adding its schema to the sampler grammar.
    if (pluginLikely && allPluginDefs.length) tools.push(...pluginGatewayDefs);
    if (memoryIntent) tools.push(...memoryDefs);

    const seen = new Set();
    return tools.filter((tool) => {
      const name = tool.function?.name;
      if (!name || seen.has(name)) return false;
      seen.add(name);
      return true;
    });
  }

  async executeTool(name, args, context = {}) {
    const projectId = context.projectId !== undefined ? context.projectId : this.project.id;
    const projectRecord = projectId ? this.project.store?.get(projectId) : null;
    const baseApprove = context.approve;
    const policyApprove = async (approval = {}) => {
      if (!this.policy) return typeof baseApprove === 'function' ? baseApprove(approval) : true;
      return this.policy.authorize({ tool: name, args: { ...(args || {}), ...(approval.args || {}) }, projectNative: !!projectRecord?.nativePath, approval }, baseApprove);
    };
    const toolContext = { ...context, projectId, approve: policyApprove };
    if (!context.fromHook) await this.hooks?.emit?.('BeforeTool', { name, args, context: toolContext });
    if (!context.fromHook && ['write_file', 'edit_file', 'replace_in_file'].includes(name)) await this.hooks?.emit?.('BeforeEdit', { name, args, context: toolContext });
    if (!context.fromHook && name === 'verify_project') await this.hooks?.emit?.('BeforeVerify', { name, args, context: toolContext });
    try {
      let result;
      if (this.toolRegistry) result = await this.toolRegistry.execute(name, args, toolContext);
      else if (this.artifacts.definitions.some((t) => t.function.name === name)) result = await this.artifacts.execute(name, args, { conversationId: context.conversationId, projectId });
      else result = await this.project.execute(name, args, { approve: policyApprove });
      if (!context.fromHook && ['write_file', 'edit_file', 'replace_in_file'].includes(name) && result?.status === 'ok') await this.hooks?.emit?.('AfterEdit', { name, args, result, context: toolContext });
      if (!context.fromHook && name === 'verify_project' && result?.ok === false) await this.hooks?.emit?.('VerificationFailed', { name, args, result, context: toolContext });
      if (!context.fromHook) await this.hooks?.emit?.('AfterTool', { name, args, result, context: toolContext });
      return result;
    } catch (error) {
      if (!context.fromHook) await this.hooks?.emit?.('ToolFailed', { name, args, error: error?.message || String(error), context: toolContext });
      throw error;
    }
  }

  async run({ mode, messages, attachment, conversationId, projectId: requestedProjectId = undefined, reasoningProfile = 'auto', greedMode = false, crewMode = 'auto', recoveryContext = '', onText, onReasoning, onTool, onArtifact, onState, onMetrics, onSkills, onMemory, onCrew, approve }) {
    const lastUser = [...messages].reverse().find((m) => m.role === 'user')?.content || '';
    const projectId = requestedProjectId !== undefined ? requestedProjectId : (this.project.id || null);
    const projectRecord = projectId ? this.project.store?.get(projectId) : null;
    const hasProject = !!projectId && (!!this.project.root || !!projectRecord?.handle || !!projectRecord?.nativePath);
    let projectSnapshot = null;
    if (mode === 'work' && hasProject) {
      try { projectSnapshot = await this.project.projectSnapshot(projectId, { refresh: true, maxEntries: 120 }); } catch {}
    }
    const conversationArtifacts = this.artifacts.list(conversationId);
    const hasArtifacts = conversationArtifacts.some((item) => ['html', 'code', 'text', 'markdown', 'document'].includes(item.type));
    const rawTools = this.toolDefinitions(mode, { prompt: lastUser, conversationId, projectId });
    const tools = grammarSafeTools(rawTools, this.runtime.capabilities?.dynamicTools ? 64 : 24);
    const healInvocation = (name, args = {}) => repairToolInvocation(name, args, rawTools);
    const compacted = compactConversation(messages, {
      contextSize: this.runtime.contextSize || 32768,
      reserveTokens: mode === 'work' ? (greedMode ? 12500 : 11000) : (greedMode ? 8500 : 7000),
      maxMessages: mode === 'work' ? (greedMode ? 14 : 24) : (greedMode ? 18 : 30),
    });
    const activeSkills = this.skills?.resolve(lastUser, { mode, hasProject, hasArtifacts, maxAuto: 3 }) || [];
    const currentWorkIntent = mode === 'work' ? workToolIntent(lastUser, { hasProject, hasArtifacts }) : null;
    onSkills?.(activeSkills.map((skill) => ({ id: skill.id, name: skill.name, reason: skill.reason || skill.mode || 'auto' })));
    const requireToolInitially = shouldRequireTool(mode, lastUser, tools, { hasProject, hasAttachment: !!attachment, hasArtifacts });
    // Runtimes without native tool transport use BlackRiver's compatibility
    // protocol. Also proactively avoid llama.cpp native grammar when the current
    // tool surface is large/complex enough to reproduce the MCP grammar crash
    // seen in the user's server logs. Relevant MCP routing should normally keep
    // this below the threshold; the fallback is a final safety net.
    const grammarRisk = !this.runtime.capabilities?.dynamicTools && nativeGrammarRisk(tools);
    const forcePromptToolFallback = !!tools.length && (this.runtime.capabilities?.nativeTools === false || grammarRisk);
    const projectContext = mode === 'work' && hasProject ? buildProjectContext(projectRecord, projectSnapshot, { query: lastUser, greed: !!greedMode }) : '';
    const memoryResolved = this.memory?.contextBlock?.(lastUser, { projectId: projectId || '', conversationId: conversationId || '', max: greedMode ? 5 : 8, greed: !!greedMode }) || { memories: [], text: '' };
    onMemory?.(memoryResolved.memories || []);
    let crewBriefs = [];
    if (mode === 'work' && this.crew) {
      try {
        crewBriefs = await this.crew.runPreflight({
          prompt: lastUser, crewMode, hasProject, hasArtifacts, greed: !!greedMode, projectContext, memoryContext: memoryResolved.text || '',
          toolDefinitions: rawTools,
          executeTool: (name, args) => this.executeTool(name, args, { conversationId, projectId, approve, specialist: true }),
          onSpawn: (role) => this.hooks?.emit?.('AgentSpawn', { role: role?.name || role?.id || 'Specialist', roleId: role?.id || '', conversationId, projectId, context: { conversationId, projectId, approve } }),
          onEvent: (event) => { onCrew?.(event); if (event?.label) onState?.({ phase: 'crew', label: event.label }); },
        });
      } catch {}
    }
    const crewContext = this.crew?.formatBriefs?.(crewBriefs) || '';
    const activeArtifact = conversationArtifacts.find((item) => item.id === this.artifacts.lastTouchedId)
      || conversationArtifacts.find((item) => item.id === this.artifacts.activeId)
      || conversationArtifacts.find((item) => ['html', 'code', 'text', 'markdown', 'document'].includes(item.type))
      || null;
    const behaviorQaRequired = !!(currentWorkIntent?.behaviorProblem && activeArtifact?.type === 'html' && rawTools.some((tool) => String(tool?.function?.name || '').startsWith('browser_')));
    const timingQaRequired = !!(behaviorQaRequired && currentWorkIntent?.timingProblem);
    const behaviorQaEvidence = new Set();
    let behaviorQaPrompts = 0;
    const behaviorQaSatisfied = () => {
      if (!behaviorQaRequired) return true;
      const observed = ['browser_click', 'browser_type', 'browser_key', 'browser_scroll', 'browser_wait', 'browser_snapshot', 'browser_inspect'].some((name) => behaviorQaEvidence.has(name));
      if (!observed) return false;
      // Time-dependent bugs need actual elapsed runtime after the latest source
      // revision. A clean bootstrap/DOM inspection cannot prove that a game does
      // not die, freeze, race, or regress one second later.
      if (timingQaRequired && !behaviorQaEvidence.has('browser_wait')) return false;
      return true;
    };
    const artifactContext = hasArtifacts
      ? `Current conversation artifacts (newest first):\n${conversationArtifacts.filter((item) => ['html', 'code', 'text', 'markdown', 'document'].includes(item.type)).slice(0, 8).map((item) => `- ${item.id === activeArtifact?.id ? '[ACTIVE] ' : ''}${item.id} · ${item.title} · ${item.type}${item.documentFormat ? `/${item.documentFormat}` : ''}`).join('\n')}\nIf the user's follow-up refers naturally to something BlackRiver just made, use the ACTIVE/newest artifact id instead of searching the project filesystem.`
      : '';
    const baseSystem = mode === 'work' ? workSystem({
      hasProject,
      hasArtifacts,
      projectName: projectRecord?.name || this.project.name,
      projectInstructions: projectRecord?.instructions || this.project.instructions,
      pinnedContext: projectRecord?.pinnedContext || this.project.pinnedContext,
      projectFiles: projectSnapshot?.files || projectRecord?.fileIndex?.filter((entry) => entry.kind === 'file').map((entry) => entry.path) || [],
      projectContext,
      nativeProject: !!projectRecord?.nativePath,
      artifactContext,
      greed: !!greedMode,
    }) : `${CHAT_SYSTEM}${greedMode ? '\n\nGREED mode is active: maximize useful work per token. Be concise, avoid repetition and unnecessary exposition, but never omit required work or reduce correctness.' : ''}`;
    const nativeToolRequirement = !forcePromptToolFallback && tools.length && requireToolInitially && this.runtime.capabilities?.dynamicTools
      ? '\n\nFor this turn, use at least one relevant BlackRiver tool before giving the final answer. Do not guess about project/artifact state.'
      : '';
    const system = `${baseSystem}${memoryResolved.text ? `\n\n${memoryResolved.text}` : ''}${recoveryContext ? `\n\n${recoveryContext}` : ''}${crewContext ? `\n\n${crewContext}` : ''}${compacted.memory ? `\n\n${compacted.memory}` : ''}${skillSystemBlock(activeSkills)}${forcePromptToolFallback ? `\n\n${fallbackToolSystem(tools, requireToolInitially)}` : ''}${nativeToolRequirement}`;
    const oai = [{ role: 'system', content: system }, ...toOaiMessages(compacted.messages)];

    if (attachment && oai.length > 1) {
      const last = oai.at(-1);
      if (last.role === 'user') {
        last.content = [
          { type: attachment.type, data: attachment.data, mime: attachment.mime || '' },
          { type: 'text', text: typeof last.content === 'string' ? last.content : '' },
        ];
      }
    }

    let visible = '';
    let reasoningVisible = '';
    let lastMetrics = null;
    // A single Work request may require several model↔tool turns. Give account
    // runtimes a stable session key so Codex can keep one app-server thread for
    // the whole agent loop instead of rebuilding context on every tool result.
    const runtimeSessionId = conversationId || crypto.randomUUID?.() || `br_${Date.now()}_${Math.random().toString(16).slice(2)}`;
    const checkpointId = mode === 'work' && projectId ? (crypto.randomUUID?.() || `cp_${Date.now()}_${Math.random().toString(16).slice(2)}`) : '';
    if (checkpointId) { try { await this.project.store?.beginCheckpoint(projectId, { checkpointId, conversationId, label: String(lastUser || 'Work session').replace(/\s+/g, ' ').trim().slice(0, 120) || 'Work session' }); await this.hooks?.emit?.('CheckpointCreated', { checkpointId, conversationId, projectId, context: { conversationId, projectId, approve } }); } catch {} }
    const projectToolNames = new Set((hasProject ? (this.project.definitionsForProject?.(projectId) || this.project.definitions || []) : []).map((tool) => tool.function?.name).filter(Boolean));
    let projectMutated = false;
    let projectVerified = false;
    let verificationRepairs = 0;
    const noteProjectToolResult = (name, result) => {
      if (['write_file', 'edit_file', 'replace_in_file'].includes(name) && result?.status === 'ok') projectMutated = true;
      if (name === 'verify_project' && result?.ok) projectVerified = true;
    };
    let pendingArtifactRepair = null;
    let artifactRepairPrompts = 0;
    const verifyArtifactMutation = async (name, result) => {
      if (!result?.artifact_id) return result;
      if (behaviorQaRequired && ['create_artifact', 'update_artifact'].includes(name) && !result?.error) behaviorQaEvidence.clear();
      if (result?.viewer === 'opened') this.artifacts.open(result.artifact_id);
      const item = this.artifacts.get(result.artifact_id);
      onArtifact?.(item);
      if (!item || item.type !== 'html' || !['create_artifact', 'update_artifact'].includes(name)) return result;
      onState?.({ phase: 'tool', label: 'Checking artifact runtime' });
      let inspection;
      try { inspection = await this.artifacts.waitForInspection(item.id, { timeoutMs: 2800, settleMs: 950 }); }
      catch (error) { inspection = { artifact_id: item.id, healthy: null, preview_ready: false, verified: false, diagnostics: [], warning: error?.message || String(error) }; }
      const enriched = { ...result, preview_check: inspection };
      if (inspection?.healthy === false) {
        pendingArtifactRepair = { id: item.id, title: item.title, diagnostics: inspection.diagnostics || [] };
      } else if (pendingArtifactRepair?.id === item.id) {
        pendingArtifactRepair = null;
        artifactRepairPrompts = 0;
      }
      return enriched;
    };
    let pendingDynamicVision = null;
    const executeNativeRuntimeTool = async (name, args = {}) => {
      const healed = healInvocation(name, args);
      if (!healed.valid) return { error: `Tool arguments could not be repaired safely: ${healed.errors.join('; ')}` };
      if (healed.repairs.length) onTool?.({ phase: 'repair', name: healed.name, args: healed.args, result: { repaired: summarizeRepairs(healed.repairs) } });
      name = healed.name;
      args = healed.args;
      onTool?.({ phase: 'call', name, args });
      onState?.({ phase: 'tool', label: toolActivityLabel(name) });
      let result;
      try {
        if (currentWorkIntent?.artifactContinuation && projectToolNames.has(name)) {
          result = { error: 'This turn targets the existing BlackRiver Artifact, not the selected project filesystem. Use read_artifact/update_artifact/inspect_artifact unless the user explicitly redirects to project files.' };
        } else {
          result = await this.executeTool(name, args, { conversationId, approve, projectId, checkpointId, checkpointLabel: lastUser });
        }
      } catch (error) {
        result = { error: error?.message || String(error || 'Tool failed') };
      }
      result = await verifyArtifactMutation(name, result);
      const detached = detachVisionImage(result);
      result = detached.result;
      if (detached.vision && this.runtime.capabilities?.image) pendingDynamicVision = detached.vision;
      if (String(name).startsWith('browser_') && !result?.error) behaviorQaEvidence.add(name);
      noteProjectToolResult(name, result);
      onTool?.({ phase: 'result', name, args, result });
      return result;
    };
    const executedFingerprints = new Map();
    let promptToolFallback = forcePromptToolFallback;

    for (let turn = 0; turn < this.maxTurns; turn++) {
      onState?.({ phase: 'prefill', label: turn === 0 ? 'Reading context' : 'Continuing' });
      let rawContent = '';
      let turnReasoning = '';
      let finishReason = null;
      let sawVisibleContent = false;
      let sawReasoning = false;
      const toolMap = {};
      const announcedTools = new Set();
      // On a creation turn where Work explicitly requires an artifact tool, keep
      // direct assistant content buffered until we know whether the model obeyed
      // the tool call. This prevents a non-compliant model from streaming an
      // entire HTML document into the conversation before we can recover it.
      const bufferRequiredArtifactContent = turn === 0 && requireToolInitially && tools.some((tool) => tool.function?.name === 'create_artifact');
      // Work should feel like an agent, not a transcript of its scratchpad. When
      // tools are available, keep pre-tool prose private until we know this turn
      // is actually the final answer. Tool/activity state remains visible through
      // onState/onTool, so the UI stays alive without dumping model narration.
      const bufferWorkToolNarration = mode === 'work' && tools.length > 0;

      const handleChunk = (chunk) => {
        const metrics = normalizeMetrics(chunk, this.runtime.contextSize);
        if (metrics.promptProgress || metrics.generationTps || metrics.promptTps || metrics.used) {
          lastMetrics = {
            ...(lastMetrics || {}),
            ...metrics,
            promptTps: metrics.promptTps || lastMetrics?.promptTps || 0,
            generationTpsLive: metrics.generationTpsLive || lastMetrics?.generationTpsLive || 0,
            generationTpsAverage: metrics.generationTpsAverage || lastMetrics?.generationTpsAverage || 0,
            generationTps: metrics.generationTps || lastMetrics?.generationTps || 0,
            promptProgress: metrics.promptProgress || lastMetrics?.promptProgress || null,
          };
          onMetrics?.(lastMetrics);
          if (metrics.promptProgress && !sawReasoning && !sawVisibleContent) {
            const { processed, total } = metrics.promptProgress;
            const pct = total > 0 ? Math.min(100, Math.round((processed / total) * 100)) : 0;
            onState?.({ phase: 'prefill', label: pct > 0 && pct < 100 ? `Reading context · ${pct}%` : 'Reading context' });
          }
        }

        const choice = chunk?.choices?.[0];
        if (!choice) return;
        finishReason = choice.finish_reason ?? finishReason;
        const delta = choice.delta || {};

        // llama.cpp reasoning_format=deepseek streams this field independently.
        // Wllama forwards the JSON even though older TS typings did not enumerate it.
        const reasoningDelta = delta.reasoning_content ?? delta.reasoning ?? '';
        if (reasoningDelta) {
          turnReasoning += reasoningDelta;
          sawReasoning = true;
          onState?.({ phase: 'thinking', label: 'Thinking' });
        }

        if (delta.content) {
          rawContent += delta.content;
          const inline = splitInlineReasoning(rawContent);
          if (inline.reasoning) {
            sawReasoning = true;
            onState?.({ phase: 'thinking', label: 'Thinking' });
          }
          if (inline.content) {
            sawVisibleContent = true;
            onState?.({ phase: 'responding', label: 'Responding' });
          }
        }

        for (const tc of delta.tool_calls || []) {
          mergeToolDelta(toolMap, tc);
          const entry = toolMap[tc.index ?? 0];
          if (entry?.name && !announcedTools.has(entry.name)) {
            announcedTools.add(entry.name);
            onState?.({ phase: 'tool', label: toolActivityLabel(entry.name) });
          }
        }

        const inline = splitInlineReasoning(rawContent);
        const cleanContent = stripToolMarkup(inline.content);
        const currentReasoning = mergeReasoning(reasoningVisible, mergeReasoning(turnReasoning, inline.reasoning));
        onText?.(visible + ((bufferRequiredArtifactContent || bufferWorkToolNarration) ? '' : cleanContent));
        onReasoning?.(currentReasoning);
      };

      const chatParams = {
        messages: oai,
        blackriver_session_id: runtimeSessionId,
        blackriver_conversation_id: conversationId || '',
        blackriver_mode: mode,
        ...(this.runtime.capabilities?.dynamicTools ? { blackriver_tool_executor: executeNativeRuntimeTool } : {}),
        ...reasoningRequestOptions(reasoningProfile),
        ...(!promptToolFallback && tools.length ? {
          tools,
          tool_choice: turn === 0 && requireToolInitially ? 'required' : 'auto',
        } : {}),
      };
      try {
        await this.runtime.chat(chatParams, handleChunk);
      } catch (error) {
        const pristine = !rawContent && !turnReasoning && !Object.keys(toolMap).length;
        if (!promptToolFallback && tools.length && pristine && isGrammarToolError(error)) {
          promptToolFallback = true;
          onState?.({ phase: 'prefill', label: 'Using compatible tool transport' });
          // Some llama.cpp chat templates (including Qwen variants) require the
          // system message to be the very first message. Never append a second
          // system role after user history; merge compatibility instructions into
          // BlackRiver's single leading system block instead.
          const compatibility = fallbackToolSystem(tools, turn === 0 && requireToolInitially);
          if (!String(oai[0]?.content || '').includes('BlackRiver compatible tool transport')) {
            oai[0].content = `${oai[0].content}\n\n${compatibility}`;
          }
          await this.runtime.chat({ messages: oai, blackriver_session_id: runtimeSessionId, blackriver_conversation_id: conversationId || '', blackriver_mode: mode, ...reasoningRequestOptions(reasoningProfile) }, handleChunk);
        } else {
          throw error;
        }
      }

      const inline = splitInlineReasoning(rawContent);
      const cleanContent = stripToolMarkup(inline.content);
      turnReasoning = mergeReasoning(turnReasoning, inline.reasoning);
      reasoningVisible = mergeReasoning(reasoningVisible, turnReasoning);

      if (pendingDynamicVision) {
        const imageMessage = visionFollowupMessage(pendingDynamicVision);
        pendingDynamicVision = null;
        if (imageMessage) {
          oai.push({ role: 'assistant', content: cleanContent || 'Browser Lab captured the rendered artifact.' });
          oai.push(imageMessage);
          onState?.({ phase: 'tool', label: 'Reviewing artifact visually' });
          continue;
        }
      }

      let calls = Object.values(toolMap).filter((tc) => tc.name);
      if (!calls.length) calls = parseFallbackToolCalls(rawContent);

      if (!calls.length) {
        if (bufferRequiredArtifactContent) {
          const recovered = recoverDirectArtifact(cleanContent, lastUser);
          if (recovered) {
            const toolName = 'create_artifact';
            onTool?.({ phase: 'call', name: toolName, args: recovered });
            onState?.({ phase: 'tool', label: 'Building artifact' });
            let result;
            try {
              result = await this.executeTool(toolName, recovered, { conversationId, approve, projectId, checkpointId, checkpointLabel: lastUser });
            } catch (error) {
              result = { error: error?.message || String(error || 'Artifact recovery failed') };
            }
            result = await verifyArtifactMutation(toolName, result);
            onTool?.({ phase: 'result', name: toolName, args: recovered, result });
            if (!result?.error && result?.artifact_id) {
              const item = this.artifacts.get(result.artifact_id);
              if (pendingArtifactRepair) {
                artifactRepairPrompts += 1;
                const errors = pendingArtifactRepair.diagnostics.map((entry) => `- ${entry.message}`).join('\n') || '- Preview runtime error detected.';
                oai.push({ role: 'assistant', content: 'Created the requested BlackRiver artifact.' });
                oai.push({ role: 'user', content: `BlackRiver Artifact Intelligence verification gate: the SAME artifact ${pendingArtifactRepair.id} (${pendingArtifactRepair.title}) rendered with runtime/console errors:
${errors}
Read/update this same artifact, fix the errors, and let BlackRiver verify it again before finishing.` });
                onState?.({ phase: 'tool', label: 'Repairing artifact runtime' });
                continue;
              }
              visible += `Created **${item?.title || recovered.title}** and opened it in the Artifact Viewer.`;
              onText?.(visible);
              onReasoning?.(reasoningVisible);
              onState?.({ phase: 'done', label: 'Artifact ready' });
              await this.hooks?.emit?.('TaskComplete', { conversationId, projectId, checkpointId, context: { conversationId, projectId, approve } });
              if (checkpointId) { try { await this.project.store?.completeCheckpoint(projectId, checkpointId); } catch {} }
              return {
                content: visible.trim(),
                checkpointId,
                reasoning: reasoningVisible,
                finishReason: finishReason || 'stop',
                metrics: lastMetrics,
                recoveredArtifact: true,
                artifactId: result.artifact_id,
              };
            }
          }
        }

        if (behaviorQaRequired && !behaviorQaSatisfied() && behaviorQaPrompts < 2) {
          behaviorQaPrompts += 1;
          oai.push({ role: 'assistant', content: cleanContent || 'Artifact source was updated.' });
          oai.push({ role: 'user', content: `BlackRiver Behavior QA Gate: the user reported a behavioral/runtime interaction problem in the existing HTML Artifact. Console-clean is not enough. Use the built-in browser_* tools on the SAME Artifact to exercise or observe the relevant behavior after the latest source revision. For timing/game-loop bugs you MUST use browser_wait after the relevant interaction or start state so elapsed runtime is part of the evidence. Only finish when the evidence matches the requested fix. Browser Lab is QA only; source changes must use update_artifact.` });
          onState?.({ phase: 'tool', label: 'Testing artifact behavior' });
          continue;
        }

        if (mode === 'work' && projectMutated && !projectVerified && !!projectRecord?.nativePath && projectToolNames.has('verify_project')) {
          onTool?.({ phase: 'call', name: 'verify_project', args: { max_checks: greedMode ? 2 : 3 } });
          onState?.({ phase: 'tool', label: 'Verifying project' });
          let verification;
          try { verification = await this.executeTool('verify_project', { max_checks: greedMode ? 2 : 3 }, { conversationId, approve, projectId, checkpointId, checkpointLabel: lastUser }); }
          catch (error) { verification = { error: error?.message || String(error), ok: false }; }
          noteProjectToolResult('verify_project', verification);
          onTool?.({ phase: 'result', name: 'verify_project', args: { max_checks: greedMode ? 2 : 3 }, result: verification });
          if (verification?.status === 'denied' || verification?.status === 'no-plan') {
            projectVerified = verification?.status === 'no-plan';
          } else if (!verification?.ok && verificationRepairs < 2) {
            verificationRepairs += 1;
            const failed = (verification?.results || []).find((item) => !item.ok);
            const details = [failed?.command ? `Command: ${failed.command}` : '', failed?.stderr || failed?.stdout || verification?.error || verification?.summary || 'Verification failed.'].filter(Boolean).join('\n');
            oai.push({ role: 'assistant', content: cleanContent || 'Implementation attempted.' });
            oai.push({ role: 'user', content: `BlackRiver Verification Gate: do not finish yet. Automatic project verification failed.\n${details.slice(0, 12000)}\nInspect the relevant files, repair the implementation, and verify again.` });
            onState?.({ phase: 'tool', label: 'Repairing verification failure' });
            continue;
          } else if (verification?.ok) {
            projectVerified = true;
          }
        }

        if (pendingArtifactRepair && artifactRepairPrompts < 3) {
          artifactRepairPrompts += 1;
          const errors = pendingArtifactRepair.diagnostics.map((entry) => `- ${entry.message}`).join('\n') || '- Preview runtime error detected.';
          oai.push({ role: 'assistant', content: cleanContent || 'Artifact update attempted.' });
          oai.push({ role: 'user', content: `BlackRiver Artifact Intelligence verification gate: do not finish yet. Artifact ${pendingArtifactRepair.id} (${pendingArtifactRepair.title}) still has runtime/console errors:
${errors}
Repair the SAME artifact with update_artifact, then wait for the automatic preview check. Do not create a replacement.` });
          onState?.({ phase: 'tool', label: 'Repairing artifact runtime' });
          continue;
        }
        if (pendingArtifactRepair && artifactRepairPrompts >= 3) {
          const errors = pendingArtifactRepair.diagnostics.map((entry) => entry.message).filter(Boolean).join('; ');
          visible += `${cleanContent ? `${cleanContent.trim()}\n\n` : ''}Artifact verification still reports: ${errors || 'a runtime error'}.`;
        } else {
          visible += cleanContent;
        }
        onText?.(visible);
        onReasoning?.(reasoningVisible);
        onState?.({ phase: 'done', label: 'Done' });
        await this.hooks?.emit?.('TaskComplete', { conversationId, projectId, checkpointId, context: { conversationId, projectId, approve } });
        if (checkpointId) { try { await this.project.store?.completeCheckpoint(projectId, checkpointId); } catch {} }
        return { content: visible.trim(), reasoning: reasoningVisible, finishReason, metrics: lastMetrics, checkpointId };
      }

      if (!bufferWorkToolNarration && cleanContent && !/^(i(?:'ll| will| am)|let me|i'm going to)\b/i.test(cleanContent.trim())) {
        visible += `${cleanContent.trim()}\n`;
      }

      const normalizedCalls = calls.map((tc, index) => ({
        id: tc.id || `call_${turn}_${index}_${Math.random().toString(16).slice(2, 8)}`,
        type: 'function',
        function: { name: tc.name, arguments: tc.arguments || '{}' },
      }));
      if (promptToolFallback) {
        oai.push({ role: 'assistant', content: rawContent || cleanContent || `Using BlackRiver tool ${normalizedCalls[0]?.function?.name || ''}.` });
      } else {
        oai.push({
          role: 'assistant', content: cleanContent || null,
          ...(turnReasoning ? { reasoning_content: turnReasoning } : {}),
          tool_calls: normalizedCalls,
        });
      }

      for (const call of normalizedCalls) {
        const parsedArgs = safeJson(call.function.arguments);
        if (parsedArgs === null) {
          const result = { error: 'Invalid JSON arguments returned by the model; BlackRiver could not repair them safely.' };
          if (promptToolFallback) oai.push({ role: 'user', content: `BlackRiver tool result · ${call.function.name}
${JSON.stringify(result)}` });
          else oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args: {}, result });
          continue;
        }
        const healed = healInvocation(call.function.name, parsedArgs);
        if (!healed.valid) {
          const result = { error: `Tool arguments could not be repaired safely: ${healed.errors.join('; ')}` };
          if (promptToolFallback) oai.push({ role: 'user', content: `BlackRiver tool result · ${call.function.name}
${JSON.stringify(result)}` });
          else oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args: parsedArgs, result });
          continue;
        }
        const args = healed.args;
        call.function.name = healed.name;
        if (healed.repairs.length) onTool?.({ phase: 'repair', name: healed.name, args, result: { repaired: summarizeRepairs(healed.repairs) } });

        const fingerprint = `${call.function.name}:${JSON.stringify(args)}`;
        const count = (executedFingerprints.get(fingerprint) || 0) + 1;
        executedFingerprints.set(fingerprint, count);
        if (count > 2) {
          const result = { error: 'Duplicate tool call suppressed. Use the existing result and continue.' };
          if (promptToolFallback) oai.push({ role: 'user', content: `BlackRiver tool result · ${call.function.name}\n${JSON.stringify(result)}` });
          else oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
          onTool?.({ phase: 'result', name: call.function.name, args, result });
          continue;
        }

        onTool?.({ phase: 'call', name: call.function.name, args });
        onState?.({ phase: 'tool', label: toolActivityLabel(call.function.name) });
        let result;
        try {
          if (currentWorkIntent?.artifactContinuation && projectToolNames.has(call.function.name)) {
            result = { error: 'This turn targets the existing BlackRiver Artifact, not the selected project filesystem. Use read_artifact/update_artifact/inspect_artifact unless the user explicitly redirects to project files.' };
          } else {
            result = await this.executeTool(call.function.name, args, { conversationId, approve, projectId, checkpointId, checkpointLabel: lastUser });
          }
        } catch (error) {
          result = { error: error?.message || String(error || 'Tool failed') };
        }
        result = await verifyArtifactMutation(call.function.name, result);
        const detached = detachVisionImage(result);
        result = detached.result;
        if (String(call.function.name).startsWith('browser_') && !result?.error) behaviorQaEvidence.add(call.function.name);
        noteProjectToolResult(call.function.name, result);
        onTool?.({ phase: 'result', name: call.function.name, args, result });
        if (promptToolFallback) oai.push({ role: 'user', content: `BlackRiver tool result · ${call.function.name}
${JSON.stringify(result)}` });
        else oai.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result) });
        if (detached.vision && this.runtime.capabilities?.image) {
          const imageMessage = visionFollowupMessage(detached.vision);
          if (imageMessage) oai.push(imageMessage);
        }
      }
    }

    onState?.({ phase: 'done', label: 'Turn limit reached' });
    await this.hooks?.emit?.('TaskComplete', { conversationId, projectId, checkpointId, incomplete: true, context: { conversationId, projectId, approve } });
    if (checkpointId) { try { await this.project.store?.completeCheckpoint(projectId, checkpointId); } catch {} }
    return {
      checkpointId,
      content: visible.trim() || 'I reached the Work turn limit before completing the task.',
      reasoning: reasoningVisible,
      finishReason: 'length',
      maxTurnsReached: true,
      metrics: lastMetrics,
    };
  }
}

export { grammarSafeSchema, grammarSafeTools, isGrammarToolError };
