function textOf(message) {
  const content = message?.content;
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return content == null ? '' : String(content);
  return content.filter((part) => part?.type === 'text').map((part) => String(part.text || '')).join('\n');
}

function lexicalTokens(value = '') {
  return new Set(String(value || '').toLowerCase().match(/[\p{L}\p{N}_./+-]{2,}/gu) || []);
}

function scorePath(path = '', queryTokens = new Set(), recent = new Set(), changed = new Set()) {
  const clean = String(path || '').replace(/\\/g, '/');
  const lower = clean.toLowerCase();
  const parts = lexicalTokens(lower.replace(/[/.\\_-]+/g, ' '));
  let score = 0;
  for (const token of queryTokens) {
    if (lower.includes(token)) score += token.length > 5 ? 3 : 1.5;
    if (parts.has(token)) score += 1;
  }
  if (changed.has(clean)) score += 7;
  if (recent.has(clean)) score += 4;
  if (/(^|\/)(package\.json|pyproject\.toml|cargo\.toml|go\.mod|cmakelists\.txt|readme\.md|vite\.config\.|tsconfig\.json|src\/main\.|src\/index\.)/i.test(clean)) score += 1.6;
  if (/\.(lock|map|min\.js|min\.css)$/i.test(clean)) score -= 2;
  return score;
}

export function compactConversation(messages = [], { contextSize = 32768, reserveTokens = 9000, maxMessages = 26 } = {}) {
  const cleaned = messages.filter((item) => item?.role === 'user' || item?.role === 'assistant');
  const budgetChars = Math.max(24000, Math.min(220000, (Math.max(8192, Number(contextSize) || 32768) - reserveTokens) * 3.2));
  let used = 0;
  const kept = [];
  for (let i = cleaned.length - 1; i >= 0; i--) {
    const item = cleaned[i];
    const size = textOf(item).length + String(item.reasoning || '').length * 0.25 + 120;
    if (kept.length >= maxMessages || (kept.length >= 8 && used + size > budgetChars)) break;
    kept.unshift(item);
    used += size;
  }
  const omitted = cleaned.slice(0, Math.max(0, cleaned.length - kept.length));
  if (!omitted.length) return { messages: kept, memory: '', compacted: 0 };

  const memoryLines = [];
  let memoryChars = 0;
  for (const item of omitted.slice(-24)) {
    if (memoryChars > 12000) break;
    const role = item.role === 'assistant' ? 'Assistant' : 'User';
    const text = textOf(item).replace(/\s+/g, ' ').trim();
    if (!text) continue;
    const line = `${role}: ${text.slice(0, 700)}`;
    memoryLines.push(line);
    memoryChars += line.length;
  }
  return {
    messages: kept,
    compacted: omitted.length,
    memory: memoryLines.length ? `Earlier conversation memory (compacted by BlackRiver Context Engine):\n${memoryLines.join('\n')}` : '',
  };
}

export function rankProjectFiles(files = [], query = '', { recentFiles = [], changedFiles = [], limit = 100 } = {}) {
  const queryTokens = lexicalTokens(query);
  const recent = new Set((recentFiles || []).map(String));
  const changed = new Set((changedFiles || []).map((entry) => typeof entry === 'string' ? entry : entry?.path).filter(Boolean));
  return [...files].map((path, index) => ({ path, index, score: scorePath(path, queryTokens, recent, changed) }))
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .slice(0, Math.max(1, Math.min(Number(limit) || 100, 180)))
    .map((item) => item.path);
}

export function buildProjectContext(record = null, snapshot = null, { query = '', greed = false } = {}) {
  if (!record) return '';
  const changedEntries = (record.changedFiles || []).slice(0, 20);
  const changed = changedEntries.map((entry) => `${entry.status?.[0]?.toUpperCase() || 'M'} ${entry.path}`);
  const recent = (record.recentFiles || []).slice(0, greed ? 10 : 16);
  const sourceFiles = snapshot?.files || record.fileIndex?.filter((entry) => entry.kind === 'file').map((entry) => entry.path) || [];
  const files = rankProjectFiles(sourceFiles, query, {
    recentFiles: record.recentFiles || [],
    changedFiles: changedEntries,
    limit: greed ? 55 : 100,
  });
  const chunks = [`BlackRiver Context Index · ${record.name}`];
  if (record.nativePath) chunks.push(`Native root: ${record.nativePath}`);
  if (changed.length) chunks.push(`Changed files (hot):\n${changed.map((item) => `- ${item}`).join('\n')}`);
  if (recent.length) chunks.push(`Recently touched:\n${recent.map((item) => `- ${item}`).join('\n')}`);
  if (files.length) chunks.push(`Relevant project map (${files.length}${(snapshot?.indexedCount || sourceFiles.length) > files.length ? '+' : ''} shown):\n${files.map((item) => `- ${item}`).join('\n')}`);
  return chunks.join('\n\n');
}
