import { nativeAvailable, nativeCore } from '../native/native-bridge.js';
import { legacyReasoningProfile } from './reasoning-adapter.js';

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  const step = 0x8000;
  for (let i = 0; i < bytes.length; i += step) binary += String.fromCharCode(...bytes.subarray(i, i + step));
  return btoa(binary);
}

function dataUrl(buffer, mime = 'image/png') {
  return `data:${mime};base64,${arrayBufferToBase64(buffer)}`;
}

function textOfContent(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return content == null ? '' : String(content);
  return content.filter((part) => part?.type === 'text').map((part) => String(part.text || '')).join('\n');
}

function finalInputFromContent(content) {
  if (!Array.isArray(content)) return [{ type: 'text', text: content == null ? '' : String(content) }];
  const out = [];
  for (const part of content) {
    if (part?.type === 'text' && String(part.text || '')) out.push({ type: 'text', text: String(part.text || '') });
    else if (part?.type === 'image' && part.data instanceof ArrayBuffer) out.push({ type: 'image', url: dataUrl(part.data, part.mime || 'image/png') });
    else if (part?.type === 'image_url' && part.image_url?.url) out.push({ type: 'image', url: String(part.image_url.url) });
  }
  return out.length ? out : [{ type: 'text', text: '' }];
}

function responseHistoryItem(message) {
  const role = message?.role === 'assistant' ? 'assistant' : 'user';
  const text = textOfContent(message?.content);
  if (!text) return null;
  return {
    type: 'message',
    role,
    content: [{ type: role === 'assistant' ? 'output_text' : 'input_text', text }],
  };
}

function flattenedTranscript(messages = []) {
  return messages
    .filter((message) => !['system', 'developer'].includes(message?.role))
    .map((message) => `${String(message?.role || 'user').toUpperCase()}: ${textOfContent(message?.content)}`)
    .join('\n\n');
}

function codexUsage(raw = {}) {
  const total = raw?.totalTokenUsage || raw?.total || raw?.usage || raw || {};
  const prompt = Number(total.inputTokens ?? total.input_tokens ?? total.promptTokens ?? total.prompt_tokens ?? 0) || 0;
  const completion = Number(total.outputTokens ?? total.output_tokens ?? total.completionTokens ?? total.completion_tokens ?? 0) || 0;
  const cached = Number(total.cachedInputTokens ?? total.cached_input_tokens ?? 0) || 0;
  return {
    prompt_tokens: prompt,
    completion_tokens: completion,
    total_tokens: Number(total.totalTokens ?? total.total_tokens ?? (prompt + completion)) || (prompt + completion),
    prompt_tokens_details: { cached_tokens: cached },
  };
}

function supportedEfforts(meta = {}) {
  return (meta.supportedReasoningEfforts || [])
    .map((entry) => typeof entry === 'string' ? entry : entry?.reasoningEffort)
    .filter(Boolean)
    .map(String);
}

function chooseEffort(params = {}, meta = {}) {
  const efforts = supportedEfforts(meta);
  const requested = legacyReasoningProfile(params, 'auto');
  if (!efforts.length) {
    if (requested === 'auto') return meta.defaultReasoningEffort || 'medium';
    if (requested === 'off') return 'none';
    return requested;
  }
  if (requested === 'auto') return meta.defaultReasoningEffort || efforts.find((value) => /^medium$/i.test(value)) || efforts[0];
  if (requested === 'off') return efforts.find((value) => /^(none|off|minimal)$/i.test(value)) || efforts[0];
  if (requested === 'low') return efforts.find((value) => /^(low|minimal)$/i.test(value)) || efforts[0];
  if (requested === 'medium') return efforts.find((value) => /^medium$/i.test(value)) || meta.defaultReasoningEffort || efforts[Math.floor((efforts.length - 1) / 2)];
  return efforts.find((value) => /^(max|xhigh)$/i.test(value))
    || efforts.find((value) => /^high$/i.test(value))
    || efforts.at(-1);
}

function toDynamicTools(tools = []) {
  const seen = new Set();
  const aliases = new Map();
  const dynamicTools = [];
  for (const tool of Array.isArray(tools) ? tools : []) {
    const fn = tool?.function || {};
    const originalName = String(fn.name || '').trim();
    if (!/^[a-zA-Z0-9_-]{1,128}$/.test(originalName)) continue;
    let name = originalName;
    // Codex reserves the `mcp` / `mcp__*` identifier family for its own MCP
    // namespace. BlackRiver MCP tools keep their ToolRegistry name internally
    // but receive a reversible provider-safe alias on the Codex wire.
    if (name === 'mcp') name = 'blackriver_mcp';
    else if (name.startsWith('mcp__')) name = `plugin_${name.slice(5)}`.slice(0, 128);
    if (!/^[a-zA-Z0-9_-]{1,128}$/.test(name) || seen.has(name)) continue;
    seen.add(name);
    aliases.set(name, originalName);
    dynamicTools.push({
      type: 'function',
      name,
      description: String(fn.description || `BlackRiver tool ${originalName}`).slice(0, 4000),
      inputSchema: fn.parameters && typeof fn.parameters === 'object' ? fn.parameters : { type: 'object', properties: {} },
    });
  }
  return { dynamicTools, aliases };
}

export class CodexAccountRuntime extends EventTarget {
  constructor() {
    super();
    this.modelId = '';
    this.modelMeta = null;
    this.catalog = [];
    this.activeTransport = null;
    this.sampling = {};
  }

  configure(modelId = '', meta = null) {
    this.modelId = String(modelId || '');
    this.modelMeta = meta || this.catalog.find((entry) => String(entry.model || entry.id) === this.modelId) || null;
    return this;
  }

  setCatalog(models = []) {
    this.catalog = Array.isArray(models) ? models : [];
    if (this.modelId) this.modelMeta = this.catalog.find((entry) => String(entry.model || entry.id) === this.modelId) || this.modelMeta;
  }

  async discoverModels() {
    if (!nativeAvailable()) throw new Error('ChatGPT / Codex models are available in BlackRiver Desktop.');
    const models = await nativeCore().codexModels();
    this.setCatalog(models);
    return models;
  }

  get isLoaded() { return !!this.modelId && nativeAvailable(); }
  get loaded() {
    if (!this.isLoaded) return null;
    return {
      source: 'codex',
      name: this.modelMeta?.displayName || this.modelId,
      modelId: this.modelId,
      providerName: 'ChatGPT / Codex',
      meta: this.modelMeta,
    };
  }
  get contextSize() { return 0; }
  get capabilities() {
    const modalities = this.modelMeta?.inputModalities || ['text', 'image'];
    return {
      image: modalities.includes('image'),
      audio: modalities.includes('audio'),
      chatTemplate: true,
      multithread: true,
      threads: 0,
      tools: true,
      nativeTools: true,
      dynamicTools: true,
      api: true,
      codex: true,
      reasoning: true,
    };
  }

  reasoningDescriptor(profile = 'auto') {
    const requested = legacyReasoningProfile({ blackriver_reasoning_profile: profile }, 'auto');
    const resolved = chooseEffort({ blackriver_reasoning_profile: requested }, this.modelMeta || {});
    return { profile: requested, label: requested === 'auto' ? 'Auto' : requested[0].toUpperCase() + requested.slice(1), hint: requested === 'auto' ? `Model default · ${resolved}` : `Codex · ${resolved}`, resolved, mode: 'codex-effort' };
  }

  setSampling(patch = {}) { this.sampling = { ...this.sampling, ...patch }; }

  async chat(params = {}, onChunk = null) {
    if (!this.isLoaded) throw new Error('Choose a ChatGPT / Codex model first.');
    const api = nativeCore();
    if (!api?.codexStream) throw new Error('This BlackRiver Desktop build does not expose the Codex runtime bridge.');
    const messages = Array.isArray(params.messages) ? params.messages : [];
    const systemParts = messages.filter((message) => ['system', 'developer'].includes(message?.role)).map((message) => textOfContent(message.content)).filter(Boolean);
    const conversational = messages.filter((message) => !['system', 'developer'].includes(message?.role));
    const lastUserIndex = (() => {
      for (let i = conversational.length - 1; i >= 0; i--) if (conversational[i]?.role === 'user') return i;
      return -1;
    })();
    if (lastUserIndex < 0) throw new Error('Codex needs a user message to start a turn.');

    const prior = conversational.slice(0, lastUserIndex);
    const lastUser = conversational[lastUserIndex];
    const history = prior.map(responseHistoryItem).filter(Boolean);
    const input = finalInputFromContent(lastUser.content);
    const effort = chooseEffort(params, this.modelMeta || {});
    const flattenedInput = `${flattenedTranscript(prior)}${prior.length ? '\n\n' : ''}USER: ${textOfContent(lastUser.content)}`;
    const { dynamicTools, aliases: dynamicToolAliases } = toDynamicTools(params.tools || []);
    const toolExecutor = typeof params.blackriver_tool_executor === 'function' ? params.blackriver_tool_executor : null;

    return new Promise((resolve, reject) => {
      let done = false;
      const transport = api.codexStream({
        model: this.modelId,
        effort,
        system: systemParts.join('\n\n'),
        history,
        input,
        flattenedInput,
        sessionId: String(params.blackriver_session_id || ''),
        conversationId: String(params.blackriver_conversation_id || ''),
        mode: String(params.blackriver_mode || 'chat'),
        dynamicTools,
      }, (event) => {
        if (!event || done) return;
        if (event.type === 'text' && event.delta) {
          onChunk?.({ model: this.modelId, choices: [{ delta: { content: String(event.delta) }, finish_reason: null }] });
        } else if (event.type === 'reasoning' && event.delta) {
          onChunk?.({ model: this.modelId, choices: [{ delta: { reasoning_content: String(event.delta) }, finish_reason: null }] });
        } else if (event.type === 'usage') {
          onChunk?.({ model: this.modelId, choices: [{ delta: {}, finish_reason: null }], usage: codexUsage(event.usage) });
        } else if (event.type === 'tool_request') {
          (async () => {
            if (!toolExecutor) {
              transport.respondTool?.(event.callId, null, `BlackRiver has no executor for tool ${event.tool || 'request'}.`);
              return;
            }
            try {
              const runtimeToolName = dynamicToolAliases.get(String(event.tool || '')) || String(event.tool || '');
              const result = await toolExecutor(runtimeToolName, event.arguments && typeof event.arguments === 'object' ? event.arguments : {});
              if (result?.error) transport.respondTool?.(event.callId, null, String(result.error));
              else transport.respondTool?.(event.callId, result, '');
            } catch (error) {
              transport.respondTool?.(event.callId, null, error?.message || String(error));
            }
          })();
        } else if (event.type === 'done') {
          done = true;
          onChunk?.({ model: this.modelId, choices: [{ delta: {}, finish_reason: 'stop' }], usage: codexUsage(event.usage || {}) });
          transport.dispose?.();
          if (this.activeTransport === transport) this.activeTransport = null;
          resolve({ ok: true });
        } else if (event.type === 'error') {
          done = true;
          transport.dispose?.();
          if (this.activeTransport === transport) this.activeTransport = null;
          reject(new Error(event.message || 'ChatGPT / Codex inference failed.'));
        }
      });
      this.activeTransport = transport;
    });
  }

  stop() {
    this.activeTransport?.cancel?.();
    this.activeTransport = null;
  }
}
