import { nativeAvailable, nativeCore } from '../native/native-bridge.js';

export class AccountManager extends EventTarget {
  constructor() {
    super();
    this.state = {
      native: nativeAvailable(),
      core: null,
      ollama: null,
      codex: null,
    };
  }

  get isNative() { return nativeAvailable(); }

  async refresh({ includeCodex = true } = {}) {
    if (!this.isNative) {
      this.state = { native: false, core: null, ollama: null, codex: null };
      this.dispatchEvent(new CustomEvent('change', { detail: this.state }));
      return this.state;
    }
    const api = nativeCore();
    const [coreStatus, ollama, codex] = await Promise.all([
      api.status().catch(() => null),
      api.ollamaStatus().catch((error) => ({ running: false, error: error.message })),
      includeCodex ? api.codexStatus().catch((error) => ({ available: false, connected: false, error: error.message })) : Promise.resolve(this.state.codex),
    ]);
    const priorModels = Array.isArray(this.state.codex?.models) ? this.state.codex.models : null;
    const nextCodex = codex ? { ...codex, ...(priorModels ? { models: priorModels } : {}) } : this.state.codex;
    this.state = { native: true, core: coreStatus, ollama, codex: nextCodex };
    this.dispatchEvent(new CustomEvent('change', { detail: this.state }));
    return this.state;
  }

  async saveApiKey(service, secret, label = '', allowedOrigins = []) {
    if (!this.isNative) return null;
    return nativeCore().saveCredential({ service, label: label || service, secret, allowedOrigins });
  }

  async removeCredential(id) {
    if (!this.isNative || !id) return false;
    return nativeCore().removeCredential(id);
  }

  async signInOllama() {
    if (!this.isNative) throw new Error('Ollama account sign-in is available in BlackRiver Desktop.');
    const result = await nativeCore().ollamaSignIn();
    await this.refresh();
    return result;
  }

  async listCodexModels() {
    if (!this.isNative) throw new Error('ChatGPT / Codex models are available in BlackRiver Desktop.');
    const models = await nativeCore().codexModels();
    this.state.codex = { ...(this.state.codex || {}), models: Array.isArray(models) ? models : [] };
    this.dispatchEvent(new CustomEvent('change', { detail: this.state }));
    return this.state.codex.models;
  }

  async signInChatGPT() {
    if (!this.isNative) throw new Error('ChatGPT / Codex sign-in is available in BlackRiver Desktop.');
    const result = await nativeCore().codexLogin();
    await this.refresh();
    try { await this.listCodexModels(); } catch {}
    return this.state;
  }

  async signOutChatGPT() {
    if (!this.isNative) return;
    await nativeCore().codexLogout();
    await this.refresh();
    if (this.state.codex) this.state.codex.models = [];
  }

  async openExternal(url) {
    if (this.isNative) return nativeCore().openExternal(url);
    window.open(url, '_blank', 'noopener,noreferrer');
  }
}
