const PROFILES = Object.freeze(['auto', 'off', 'low', 'medium', 'high']);
const FALLBACK_BUDGETS = Object.freeze({ low: 512, medium: 2048, high: 8192 });
const KNOWN_LEVELS = Object.freeze(['none', 'off', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max']);

export function normalizeReasoningProfile(value = 'auto') {
  const text = String(value || '').trim().toLowerCase();
  return PROFILES.includes(text) ? text : 'auto';
}

function uniq(values = []) {
  return [...new Set(values.map((value) => String(value || '').trim().toLowerCase()).filter(Boolean))];
}

function objectCaps(payload = {}) {
  if (!payload || typeof payload !== 'object') return {};
  return payload.chat_template_caps || payload.chatTemplateCaps || payload.caps || {};
}

function payloadTemplate(payload = {}) {
  return String(payload?.chat_template || payload?.chatTemplate || payload?.template || '');
}

function explicitLevels(caps = {}) {
  const candidates = [
    caps.reasoning_effort_levels,
    caps.reasoningEffortLevels,
    caps.supported_reasoning_efforts,
    caps.supportedReasoningEfforts,
    caps.reasoning_levels,
    caps.reasoningLevels,
  ].find(Array.isArray);
  return uniq(candidates || []);
}

function levelsFromTemplate(template = '') {
  const source = String(template || '').toLowerCase();
  if (!source) return [];
  const hasReasoningSelector = /reasoning_(?:effort|strength)|reasoning\.(?:effort|strength)/i.test(source);
  if (!hasReasoningSelector) return [];
  return KNOWN_LEVELS.filter((level) => new RegExp(`['\"]${level}['\"]`, 'i').test(source));
}

function modelHintLevels(modelId = '') {
  const id = String(modelId || '').toLowerCase();
  // Qwen3.8's current llama.cpp template uses low / medium / xhigh. Do not
  // translate BlackRiver Medium into a token cap while leaving the template at
  // its xhigh default: that truncates a deep pass instead of selecting Medium.
  if (/qwen\s*3[._-]?8|qwen3\.8/.test(id)) return ['low', 'medium', 'xhigh'];
  if (/gpt[-_. ]?oss/.test(id)) return ['low', 'medium', 'high'];
  return [];
}

export function analyzeReasoningTemplate({ modelId = '', template = '', caps = {}, payload = null } = {}) {
  const mergedCaps = { ...objectCaps(payload || {}), ...(caps || {}) };
  const rawTemplate = String(template || payloadTemplate(payload || {}) || '');
  let levels = explicitLevels(mergedCaps);
  if (!levels.length) levels = levelsFromTemplate(rawTemplate);
  if (!levels.length && (mergedCaps.supports_reasoning_effort === true || mergedCaps.supportsReasoningEffort === true)) {
    levels = modelHintLevels(modelId);
  }
  const supportsEffort = mergedCaps.supports_reasoning_effort === true
    || mergedCaps.supportsReasoningEffort === true
    || levels.length > 0
    || /reasoning_(?:effort|strength)/i.test(rawTemplate);
  const supportsThinking = mergedCaps.supports_thinking === true
    || mergedCaps.supportsThinking === true
    || mergedCaps.supports_enable_thinking === true
    || mergedCaps.supportsEnableThinking === true
    || /enable_thinking|<think>|thinking/i.test(rawTemplate)
    || supportsEffort;
  return { modelId: String(modelId || ''), template: rawTemplate, caps: mergedCaps, supportsEffort, supportsThinking, levels: uniq(levels) };
}

function pickEffort(profile, levels = []) {
  const available = uniq(levels);
  const find = (...names) => names.map((name) => available.find((value) => value === name)).find(Boolean) || '';
  if (!available.length) return profile;
  if (profile === 'off') return find('none', 'off', 'minimal');
  if (profile === 'low') return find('low', 'minimal') || available[0] || 'low';
  if (profile === 'medium') return find('medium') || find('high', 'low') || available[Math.floor((available.length - 1) / 2)] || 'medium';
  // BlackRiver has one simple High position. Resolve it to the strongest
  // semantic level the actual template exposes (max/xhigh/high), not a guessed
  // token count.
  if (profile === 'high') return find('max', 'xhigh', 'high') || available.at(-1) || 'high';
  return '';
}

export function llamaCppReasoningRequest({ profile = 'auto', modelId = '', template = '', caps = {}, payload = null, provider = 'llama.cpp' } = {}) {
  const requested = normalizeReasoningProfile(profile);
  const info = analyzeReasoningTemplate({ modelId, template, caps, payload });
  const request = {};
  if (requested === 'auto') {
    return { requested, resolved: 'auto', mode: 'template-default', request, info, note: 'Template/server default' };
  }
  if (requested === 'off') {
    request.chat_template_kwargs = { enable_thinking: false };
    // Current llama-server explicitly supports reasoning_effort=none as the
    // request-level off switch even when a model template has no named effort
    // tiers. Keep enable_thinking=false too because native Jinja templates use it.
    request.reasoning_effort = 'none';
    return { requested, resolved: 'off', mode: 'template-disable', request, info, note: 'Thinking disabled by template/server' };
  }

  if (info.supportsEffort) {
    const effort = pickEffort(requested, info.levels) || requested;
    request.reasoning_effort = effort;
    request.chat_template_kwargs = {
      enable_thinking: true,
      reasoning_effort: effort,
      // Some templates (and translated variants) use reasoning_strength rather
      // than reasoning_effort. Supplying both keeps the intent semantic.
      reasoning_strength: effort,
    };
    return { requested, resolved: effort, mode: 'template-effort', request, info, note: `Template · ${effort}` };
  }

  request.chat_template_kwargs = { enable_thinking: true };
  const budget = FALLBACK_BUDGETS[requested];
  // llama-server historically accepted thinking_budget_tokens and current builds
  // also honor the canonical reasoning_budget_tokens field per request. Keep the
  // legacy alias for HTTP llama.cpp compatibility; Wllama uses the established
  // thinking_budget_tokens surface exposed by its server-context bridge.
  request.thinking_budget_tokens = budget;
  if (provider !== 'wllama') request.reasoning_budget_tokens = budget;
  return {
    requested,
    resolved: requested,
    mode: 'budget-fallback',
    request,
    info,
    note: `Fallback budget · ${budget.toLocaleString()} tokens`,
  };
}

export function ollamaReasoningRequest({ profile = 'auto', modelId = '', modelInfo = null } = {}) {
  const requested = normalizeReasoningProfile(profile);
  const capabilities = uniq(modelInfo?.capabilities || []);
  const thinkingAdvertised = capabilities.includes('thinking');
  const id = String(modelId || '').toLowerCase();
  const gptOss = /gpt[-_. ]?oss/.test(id) || /gpt[-_. ]?oss/.test(String(modelInfo?.details?.family || '').toLowerCase());
  const request = {};

  if (requested === 'auto') return { requested, resolved: 'auto', mode: 'provider-default', request, note: 'Ollama model default', thinkingAdvertised };
  // Imported GGUFs can reason even when /api/show does not advertise the
  // thinking capability. In that ambiguous case, omit `think` rather than send
  // a field Ollama may reject with HTTP 400.
  if (!thinkingAdvertised && !gptOss) {
    return { requested, resolved: 'auto', mode: 'capability-unknown', request, note: 'Model does not advertise thinking · using template default', thinkingAdvertised };
  }
  if (gptOss) {
    const level = requested === 'off' ? 'low' : requested;
    request.think = ['low', 'medium', 'high'].includes(level) ? level : 'medium';
    return {
      requested,
      resolved: request.think,
      mode: 'ollama-level',
      request,
      note: requested === 'off' ? 'GPT-OSS always reasons · using Low' : `Ollama · ${request.think}`,
      thinkingAdvertised: true,
    };
  }
  // Ollama documents boolean thinking for normal thinking-capable models.
  // Only GPT-OSS exposes low/medium/high effort tiers. Do not send string levels
  // to Qwen/DeepSeek/etc.; that can be rejected by the API. BlackRiver keeps the
  // simple selector, but Low/Medium/High all mean "thinking on" when the
  // provider/model exposes no finer effort control.
  if (requested === 'off') request.think = false;
  else request.think = true;
  return {
    requested,
    resolved: requested === 'off' ? 'off' : 'on',
    mode: 'ollama-boolean',
    request,
    note: requested === 'off' ? 'Ollama · thinking off' : 'Ollama · thinking on · model exposes no effort tiers',
    thinkingAdvertised: true,
  };
}

export function openAIReasoningRequest({ profile = 'auto' } = {}) {
  const requested = normalizeReasoningProfile(profile);
  if (requested === 'auto') return { requested, resolved: 'auto', mode: 'provider-default', request: {}, note: 'Provider/model default' };
  const effort = requested === 'off' ? 'none' : requested;
  return { requested, resolved: effort, mode: 'reasoning-effort', request: { reasoning_effort: effort }, note: `Reasoning · ${effort}` };
}

export function legacyReasoningProfile(params = {}, fallback = 'auto') {
  if (params.blackriver_reasoning_profile) return normalizeReasoningProfile(params.blackriver_reasoning_profile);
  if (params.chat_template_kwargs?.enable_thinking === false) return 'off';
  const budget = Number(params.thinking_budget_tokens);
  if (Number.isFinite(budget)) {
    if (budget === 0) return 'off';
    if (budget < 0 || budget >= 8192) return 'high';
    if (budget <= 1024) return 'low';
    return 'medium';
  }
  return normalizeReasoningProfile(fallback);
}

export function reasoningUiDescriptor({ provider = 'generic', profile = 'auto', modelId = '', template = '', caps = {}, payload = null, modelInfo = null } = {}) {
  const normalized = normalizeReasoningProfile(profile);
  let adapted;
  if (provider === 'llama.cpp' || provider === 'wllama') adapted = llamaCppReasoningRequest({ profile: normalized, modelId, template, caps, payload, provider });
  else if (provider === 'ollama') adapted = ollamaReasoningRequest({ profile: normalized, modelId, modelInfo });
  else adapted = openAIReasoningRequest({ profile: normalized });
  const label = normalized === 'auto' ? 'Auto' : normalized[0].toUpperCase() + normalized.slice(1);
  return { profile: normalized, label, hint: adapted.note || 'Model-aware reasoning', resolved: adapted.resolved, mode: adapted.mode };
}
