import { OpenAICompatibleRuntime } from './openai-compatible-runtime.js';

const AUTO_KEY = 'blackriver.model.auto.v1';

export class ProviderRouter extends EventTarget {
  constructor(localRuntime, providerStore, codexRuntime = null) {
    super();
    this.local = localRuntime;
    this.store = providerStore;
    this.api = new OpenAICompatibleRuntime();
    this.codex = codexRuntime;
    this.sampling = { ...localRuntime.sampling };
    try { this.autoEnabled = localStorage.getItem(AUTO_KEY) === '1'; } catch { this.autoEnabled = false; }
    this.api.addEventListener('context', (event) => this.dispatchEvent(new CustomEvent('context', { detail: event.detail })));

    localRuntime.addEventListener('status', (event) => {
      if (event.detail?.state === 'ready' && event.detail?.loaded && !this.autoEnabled) this.store.selectWllama();
      this.dispatchEvent(new CustomEvent('status', { detail: event.detail }));
    });
    localRuntime.addEventListener('hardware', (event) => this.dispatchEvent(new CustomEvent('hardware', { detail: event.detail })));
    localRuntime.addEventListener('cache-error', (event) => this.dispatchEvent(new CustomEvent('cache-error', { detail: event.detail })));
    providerStore.addEventListener('change', () => {
      this.syncSelection();
      this.dispatchEvent(new CustomEvent('provider', { detail: this.selection }));
    });
    this.syncSelection();
  }

  get selection() { return this.store.selection; }
  get concreteRuntime() { return this.selection?.kind === 'codex' ? this.codex : this.selection?.kind === 'api' ? this.api : this.local; }
  get activeRuntime() {
    // Auto is intentionally local-first and never begins spending against a new
    // cloud provider the user has not already selected. The concrete selection
    // remains the fallback; a loaded local model transparently takes priority.
    if (this.autoEnabled && this.local.isLoaded) return this.local;
    return this.concreteRuntime;
  }
  get isCodex() { return this.activeRuntime === this.codex; }
  get isOpenAICompatibleApi() { return this.activeRuntime === this.api; }
  get isApi() { return this.isOpenAICompatibleApi || this.isCodex; }
  get isLocal() { return this.activeRuntime === this.local; }
  get hardware() { return this.local.hardware; }
  get runtimeParams() { return this.local.runtimeParams; }
  get modelManager() { return this.local.modelManager; }
  get localIsLoaded() { return this.local.isLoaded; }

  syncSelection() {
    if (this.selection?.kind === 'api') {
      const provider = this.store.get(this.selection.providerId);
      this.api.configure(provider, this.selection.modelId || provider?.lastModelId || '');
      const { max_tokens: _localOnlyMaxTokens, ...apiSampling } = this.sampling;
      this.api.setSampling(apiSampling);
    } else if (this.selection?.kind === 'codex' && this.codex) {
      this.codex.configure(this.selection.modelId || '');
      this.codex.setSampling(this.sampling);
    }
  }

  syncApiSelection() { this.syncSelection(); }

  get isLoaded() { return this.activeRuntime?.isLoaded || false; }
  get loaded() { return this.activeRuntime?.loaded || null; }
  get contextSize() { return this.activeRuntime?.contextSize || 0; }
  get loadedContextInfo() { return this.isLocal ? this.local.loadedContextInfo : null; }
  get capabilities() { return this.activeRuntime?.capabilities || {}; }
  get supportsWebGPU() { return this.local.supportsWebGPU; }
  get backendLabel() {
    if (this.isCodex) return 'ChatGPT · Account';
    if (this.isOpenAICompatibleApi) return `${this.api.provider?.name || 'API'} · API`;
    return this.local.hardware.adapter ? 'Local · WebGPU' : this.local.isLoaded ? 'Local · CPU' : 'Local';
  }
  reasoningDescriptor(profile = 'auto') {
    const active = this.activeRuntime;
    if (typeof active?.reasoningDescriptor === 'function') return active.reasoningDescriptor(profile);
    return { profile, label: profile === 'auto' ? 'Auto' : String(profile || 'auto'), hint: 'Model-aware reasoning', resolved: profile, mode: 'provider-default' };
  }

  get inferenceLabel() {
    const prefix = this.autoEnabled ? 'Auto · ' : '';
    if (this.isCodex) return `${prefix}ChatGPT / Codex · ${this.codex?.modelMeta?.displayName || this.codex?.modelId || 'model'}`;
    if (this.isOpenAICompatibleApi) return `${prefix}${this.api.provider?.name || 'API'} · ${this.api.modelId || 'model'}`;
    return `${prefix}Wllama 3.6 · ${this.local.hardware.adapter ? 'WebGPU' : 'local'}`;
  }

  setAuto(enabled) {
    this.autoEnabled = !!enabled;
    try { localStorage.setItem(AUTO_KEY, this.autoEnabled ? '1' : '0'); } catch {}
    this.syncSelection();
    this.dispatchEvent(new CustomEvent('provider', { detail: { ...this.selection, auto: this.autoEnabled } }));
  }
  selectAuto() { this.setAuto(true); }

  selectApi(providerId, modelId) {
    this.setAuto(false);
    this.store.selectApi(providerId, modelId);
    this.syncSelection();
  }
  selectCodex(modelId, meta = null) {
    this.setAuto(false);
    if (!this.codex) throw new Error('ChatGPT / Codex runtime is unavailable in this build.');
    this.codex.configure(modelId, meta);
    this.store.selectCodex(modelId);
    this.syncSelection();
  }
  selectLocal() { this.setAuto(false); this.store.selectWllama(); }

  async discoverModels(provider) { return this.api.discoverModels(provider); }
  async discoverCodexModels() {
    if (!this.codex) throw new Error('ChatGPT / Codex runtime is unavailable in this build.');
    const models = await this.codex.discoverModels();
    if (this.selection?.kind === 'codex') this.codex.configure(this.selection.modelId || '', models.find((m) => String(m.model || m.id) === this.selection.modelId) || null);
    return models;
  }
  async refreshActiveModelInfo() {
    if (this.isCodex) return { contextSize: 0, payload: this.codex?.modelMeta || null };
    if (this.isOpenAICompatibleApi) return this.api.refreshModelInfo();
    return { contextSize: this.local.contextSize, payload: this.local.loadedContextInfo };
  }
  async reloadLocalCurrent(overrides = {}) {
    const result = await this.local.reloadCurrent(overrides);
    this.store.selectWllama();
    return result;
  }
  get canReloadLocalCurrent() { return !!this.local.reloadSpec; }
  async probeWebGPU(force = false) { return this.local.probeWebGPU(force); }
  async listCachedModels() { return this.local.listCachedModels(); }
  setRuntimeParams(patch) { this.local.setRuntimeParams(patch); }
  setSampling(patch) {
    this.sampling = { ...this.sampling, ...patch };
    this.local.setSampling(patch);
    const { max_tokens: _localOnlyMaxTokens, ...apiPatch } = patch || {};
    this.api.setSampling(apiPatch);
    this.codex?.setSampling(patch || {});
  }

  async loadLocal(...args) { const result = await this.local.loadLocal(...args); this.store.selectWllama(); return result; }
  async loadFromUrls(...args) { const result = await this.local.loadFromUrls(...args); this.store.selectWllama(); return result; }
  async loadFromHF(...args) { const result = await this.local.loadFromHF(...args); this.store.selectWllama(); return result; }

  async chat(params, onChunk) { return this.activeRuntime.chat(params, onChunk); }
  stop() { return this.activeRuntime?.stop?.(); }
  async unload() {
    if (this.isApi) {
      this.stop();
      this.store.selectWllama();
      this.dispatchEvent(new CustomEvent('status', { detail: { state: this.local.isLoaded ? 'ready' : 'idle', message: this.local.isLoaded ? `${this.local.loaded?.name} loaded` : 'No model loaded', loaded: this.local.loaded } }));
      return;
    }
    return this.local.unload();
  }
}
